export const DataProvider = ({ children }: { children: ReactNode }) => {
  const [tasks, setTasks] = useState<Task[]>(initialTasks);
  const [settings, setSettings] = useState<SettingsState>(initialSettings);

  const addTask = (newTask: Omit<Task, 'id' | 'createdAt'>) => {
    const task: Task = {
      ...newTask,
      id: `T-${Math.floor(1000 + Math.random() * 9000)}`,
      createdAt: new Date().toISOString(),
    };
    setTasks((prev) => [task, ...prev]);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks((prev) => prev.map((t) => (t.id === id ? { ...t, ...updates } : t)));
  };

  const deleteTask = (id: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  const addSettingItem = (category: keyof SettingsState, name: string) => {
    const newItem: CatalogItem = {
      id: Math.random().toString(36).substr(2, 9),
      name,
    };
    setSettings((prev) => ({
      ...prev,
      [category]: [...prev[category], newItem],
    }));
  };

  const removeSettingItem = (category: keyof SettingsState, id: string) => {
    setSettings((prev) => ({
      ...prev,
      [category]: prev[category].filter((item) => item.id !== id),
    }));
  };

  const exportTasksToCSV = () => {
    // Simple CSV Export Logic
    const headers = ['ID', 'Local', 'Situação', 'Criticidade', 'Data Chamado'];
    const rows = tasks.map(t => [t.id, t.location, t.situation, t.criticality, t.callDate]);

    let csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(",") + "\n" 
        + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "tarefas_manutencao.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <DataContext.Provider value={{ tasks, settings, addTask, updateTask, deleteTask, addSettingItem, removeSettingItem, exportTasksToCSV }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useData must be used within a DataProvider');
  return context;
};

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { User, Role } from '../types';

interface AuthContextType {
  user: User | null;
  login: (role: Role) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);

  const login = (role: Role) => {
    // Simulate login
    setUser({
      id: 'u1',
      name: role === 'admin' ? 'Administrador Geral' : 'Operador de Campo',
      email: role === 'admin' ? 'admin@maintenance360.com' : 'op@maintenance360.com',
      role: role,
      avatar: `https://ui-avatars.com/api/?name=${role}&background=10b981&color=fff`,
    });
  };

  const logout = () => {
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

