                       </td>
                       <td className="px-6 py-4">
                          <span className={`px-2.5 py-1 rounded-full text-xs font-medium border border-transparent ${getStatusColor(task.situation)}`}>
                             {task.situation}
                          </span>
                       </td>
                       <td className="px-6 py-4">
                          <span className={`px-2.5 py-1 rounded-md text-xs font-medium border ${getCriticalityColor(task.criticality)}`}>
                             {task.criticality}
                          </span>
                       </td>
                       <td className="px-6 py-4 text-right">
                          <div className="flex items-center justify-end gap-2">
                             <button onClick={() => handleEdit(task)} className="p-1.5 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded transition-colors">
                               <Edit2 size={16} />
                             </button>
                             {user?.role === 'admin' && (
                               <button onClick={() => deleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors">
                                 <Trash2 size={16} />
                               </button>
                             )}
                          </div>
                       </td>
                    </tr>
                  ))
                )}
             </tbody>
           </table>
         </div>
      </div>

      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        initialData={editingTask}
      />
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useData } from '../../context/DataContext';
import { Task, Situation, Criticality } from '../../types';
import { X, Save, Calendar, MapPin } from 'lucide-react';

interface TaskFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialData?: Task;
}

export const TaskFormModal: React.FC<TaskFormModalProps> = ({ isOpen, onClose, initialData }) => {
  const { settings, addTask, updateTask } = useData();

  // Form State
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    sectorId: '',
    serviceId: '',
    towerId: '',
    location: '',
    responsibleId: '',
    situation: 'Aberto',
    criticality: 'Média',
    materials: [],
    callDate: new Date().toISOString().split('T')[0],
    startDate: '',
    endDate: ''
  });

  useEffect(() => {
    if (initialData) {
        setFormData({
            ...initialData,
            callDate: initialData.callDate.split('T')[0],
            startDate: initialData.startDate ? initialData.startDate.split('T')[0] : '',
            endDate: initialData.endDate ? initialData.endDate.split('T')[0] : ''
        });
    } else {
        // Reset for new entry
        setFormData({
            title: '',
            sectorId: settings.sectors[0]?.id || '',
            serviceId: settings.services[0]?.id || '',
            towerId: settings.towers[0]?.id || '',
            location: '',
            responsibleId: settings.responsibles[0]?.id || '',
            situation: 'Aberto',
            criticality: 'Média',
            materials: [],
            callDate: new Date().toISOString().split('T')[0],
            startDate: '',
            endDate: ''
        });
    }
  }, [initialData, isOpen, settings]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleMaterialToggle = (materialId: string) => {
    setFormData(prev => {
        const current = prev.materials || [];
        if (current.includes(materialId)) {
            return { ...prev, materials: current.filter(id => id !== materialId) };
        } else {
            return { ...prev, materials: [...current, materialId] };
        }
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Basic validation
    if(!formData.title || !formData.location) {
        alert("Preencha os campos obrigatórios (Título e Localização)");
        return;
    }

    if (initialData) {
        updateTask(initialData.id, formData);
    } else {
        addTask(formData as Omit<Task, 'id' | 'createdAt'>);
    }
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-fade-in">
       <div className="bg-white rounded-2xl shadow-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto">
          {/* Header */}
          <div className="sticky top-0 z-10 bg-white border-b border-slate-100 px-6 py-4 flex items-center justify-between">
             <h3 className="text-xl font-bold text-slate-800">
                {initialData ? 'Editar Tarefa' : 'Nova Ordem de Manutenção'}
             </h3>
             <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-full transition-colors">
                <X size={24} />
             </button>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-8">
             {/* Main Info Group */}
             <div className="space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Título da Tarefa *</label>
                        <input 
                           type="text" 
                           name="title" 
                           value={formData.title} 
                           onChange={handleChange}
                           className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                           placeholder="Ex: Manutenção Preventiva Motor A"
                        />
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Localização *</label>
                        <div className="relative">
                            <MapPin size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input 
                            type="text" 
                            name="location" 
                            value={formData.location} 
                            onChange={handleChange}
                            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all"
                            placeholder="Ex: Sala de Máquinas 02"
                            />
                        </div>
                    </div>
                 </div>
             </div>

             <div className="border-t border-slate-100 pt-6">
                <h4 className="text-sm uppercase tracking-wide text-slate-500 font-semibold mb-4">Detalhes Operacionais</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Setor</label>
                        <select name="sectorId" value={formData.sectorId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none">
                           {settings.sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Tipo de Serviço</label>
                        <select name="serviceId" value={formData.serviceId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none">
                           {settings.services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Torre</label>
                        <select name="towerId" value={formData.towerId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none">
                           {settings.towers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Responsável Técnico</label>
                        <select name="responsibleId" value={formData.responsibleId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none">
                           {settings.responsibles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
             </div>

             <div className="border-t border-slate-100 pt-6">
                <h4 className="text-sm uppercase tracking-wide text-slate-500 font-semibold mb-4">Status & Prioridade</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Situação</label>
                        <select name="situation" value={formData.situation} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none">
                           <option value="Aberto">Aberto</option>
                           <option value="Em Andamento">Em Andamento</option>
                           <option value="Concluído">Concluído</option>
                           <option value="Cancelado">Cancelado</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Criticidade</label>
                        <select name="criticality" value={formData.criticality} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none">
                           <option value="Baixa">Baixa</option>
                           <option value="Média">Média</option>
                           <option value="Alta">Alta</option>
                        </select>
                    </div>
                </div>
             </div>

             {/* Materials */}
             <div className="border-t border-slate-100 pt-6">
                <h4 className="text-sm uppercase tracking-wide text-slate-500 font-semibold mb-4">Materiais Disponíveis</h4>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                   {settings.materials.map(mat => (
                       <label key={mat.id} className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-all ${formData.materials?.includes(mat.id) ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>
                          <input 
                            type="checkbox" 
                            checked={formData.materials?.includes(mat.id)}
                            onChange={() => handleMaterialToggle(mat.id)}
