import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { SettingsState } from '../../types';
import { Plus, Trash2, Tag, User as UserIcon, Wrench, Briefcase, Box } from 'lucide-react';

const TABS = [
  { id: 'sectors', label: 'Setores', icon: Briefcase },
  { id: 'services', label: 'Serviços', icon: Wrench },
  { id: 'towers', label: 'Torres', icon: Box },
  { id: 'responsibles', label: 'Responsáveis', icon: UserIcon },
  { id: 'materials', label: 'Materiais', icon: Tag },
];

export const Settings = () => {
  const { settings, addSettingItem, removeSettingItem } = useData();
  const [activeTab, setActiveTab] = useState<keyof SettingsState>('sectors');
  const [newItemName, setNewItemName] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemName.trim()) {
      addSettingItem(activeTab, newItemName);
      setNewItemName('');
    }
  };

  const currentItems = settings[activeTab];

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Configurações do Sistema</h2>
        <p className="text-slate-500">Gerencie as listas auxiliares para o cadastro de tarefas</p>
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar Navigation for Settings */}
        <div className="w-full lg:w-64 flex flex-col gap-2">
           {TABS.map(tab => (
               <button
                 key={tab.id}
                 onClick={() => setActiveTab(tab.id as keyof SettingsState)}
                 className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    activeTab === tab.id 
                    ? 'bg-white text-emerald-600 shadow-sm border border-emerald-100' 
                    : 'text-slate-500 hover:bg-slate-100'
                 }`}
               >
                 <tab.icon size={18} />
                 {tab.label}
               </button>
           ))}
        </div>

        {/* Content Area */}
        <div className="flex-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100 min-h-[500px]">
           <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
              Gerenciar {TABS.find(t => t.id === activeTab)?.label}
           </h3>

           {/* Add New Item Form */}
           <form onSubmit={handleAdd} className="flex gap-3 mb-8">
              <input 
                type="text" 
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder="Nome do novo item..."
                className="flex-1 px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none"
              />
              <button 
                type="submit"
                className="bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
              >
                <Plus size={18} />
                Adicionar
              </button>
           </form>

           {/* List */}
           <div className="space-y-2">
              {currentItems.length === 0 ? (
                 <p className="text-slate-400 text-center py-8">Nenhum item cadastrado.</p>
              ) : (
                currentItems.map(item => (
                   <div key={item.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100 group hover:border-emerald-200 transition-colors">
                      <span className="text-slate-700 font-medium">{item.name}</span>
                      <button 
                        onClick={() => removeSettingItem(activeTab, item.id)}
                        className="text-slate-400 hover:text-red-500 p-2 rounded-md hover:bg-red-50 transition-colors opacity-0 group-hover:opacity-100"
                        title="Excluir item"
                      >
                         <Trash2 size={16} />
                      </button>
                   </div>
                ))
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { DataProvider } from './context/DataContext';
import { Layout } from './components/ui/Layout';
import { Login } from './components/pages/Login';
import { Dashboard } from './components/pages/Dashboard';
import { TaskList } from './components/pages/TaskList';
import { Settings } from './components/pages/Settings';

const ProtectedRoute = ({ children }: { children: React.JSX.Element }) => {
  const { user } = useAuth();
  if (!user) {
    return <Login />;
  }
  return children;
};

const AdminRoute = ({ children }: { children: React.JSX.Element }) => {
  const { user } = useAuth();
  if (user?.role !== 'admin') {
    return <Navigate to="/" replace />;
  }
  return children;
};

const AppContent = () => {
  const { user } = useAuth();

  return (
    <Routes>
      <Route path="/" element={
        <ProtectedRoute>
          <Layout />
        </ProtectedRoute>
      }>
        <Route index element={<Dashboard />} />
        <Route path="tasks" element={<TaskList />} />
        <Route path="settings" element={
          <AdminRoute>
            <Settings />
          </AdminRoute>
        } />
      </Route>
    </Routes>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <DataProvider>
        <HashRouter>
           <AppContent />
        </HashRouter>
      </DataProvider>
    </AuthProvider>
  );
}

