import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { SettingsState } from '../../types';
import { Plus, Trash2, Tag, User as UserIcon, Wrench, Briefcase, Box, Edit2, Check, X, Activity } from 'lucide-react';

const TABS = [
  { id: 'towers', label: 'Torres', icon: Box },
  { id: 'sectors', label: 'Setores', icon: Briefcase },
  { id: 'services', label: 'Tipos de Serviço', icon: Wrench },
  { id: 'responsibles', label: 'Responsáveis', icon: UserIcon },
  { id: 'situations', label: 'Situação da Tarefa', icon: Activity },
  { id: 'materials', label: 'Materiais Disponíveis', icon: Tag },
];

export const Settings = () => {
  const { settings, addSettingItem, updateSettingItem, removeSettingItem } = useData();
  const [activeTab, setActiveTab] = useState<keyof SettingsState>('towers');
  const [newItemName, setNewItemName] = useState('');

  // State for handling inline editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemName.trim()) {
      addSettingItem(activeTab, newItemName);
      setNewItemName('');
    }
  };

  const startEdit = (id: string, currentName: string) => {
    setEditingId(id);
    setEditingName(currentName);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditingName('');
  };

  const saveEdit = (id: string) => {
    if (editingName.trim()) {
      updateSettingItem(activeTab, id, editingName);
      setEditingId(null);
      setEditingName('');
    }
  };

  const currentItems = settings[activeTab];

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Configurações do Sistema</h2>
