      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar Navigation for Settings */}
        <div className="w-full lg:w-64 flex flex-col gap-2">
           {TABS.map(tab => (
               <button
                 key={tab.id}
                 onClick={() => {
                   setActiveTab(tab.id as keyof SettingsState);
                   setEditingId(null);
                 }}
                 className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    activeTab === tab.id 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                    : 'bg-white text-slate-600 hover:bg-slate-50 border border-transparent hover:border-slate-200'
                 }`}
               >
                 <tab.icon size={18} />
                 {tab.label}
               </button>
           ))}
        </div>

        {/* Content Area */}
        <div className="flex-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-200 min-h-[500px]">
           <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                  <div className="p-2 bg-blue-100 rounded-lg text-blue-600">
                    {React.createElement(TABS.find(t => t.id === activeTab)?.icon || Box, { size: 20 })}
                  </div>
                  Gerenciar {TABS.find(t => t.id === activeTab)?.label}
              </h3>
              <span className="text-xs bg-slate-100 text-slate-500 px-3 py-1 rounded-full font-medium">
                {currentItems.length} itens cadastrados
              </span>
           </div>

           {/* Add New Item Form */}
           <form onSubmit={handleAdd} className="flex gap-3 mb-8 bg-slate-50 p-4 rounded-xl border border-slate-200">
              <input 
                type="text" 
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                placeholder={`Adicionar novo em ${TABS.find(t => t.id === activeTab)?.label}...`}
                className="flex-1 px-4 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
              />
              <button 
                type="submit"
                className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-medium transition-colors flex items-center gap-2 shadow-md shadow-blue-100"
              >
                <Plus size={18} />
                <span className="hidden sm:inline">Adicionar</span>
              </button>
           </form>

           {/* List */}
           <div className="space-y-2">
              {currentItems.length === 0 ? (
                 <div className="text-center py-12 flex flex-col items-center gap-3">
                    <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-300">
                        <Box size={32} />
                    </div>
                    <p className="text-slate-400">Nenhum item cadastrado nesta categoria.</p>
                 </div>
              ) : (
                currentItems.map(item => (
                   <div key={item.id} className="flex items-center justify-between p-3 pl-4 bg-white rounded-xl border border-slate-200 group hover:border-blue-200 hover:shadow-sm transition-all">
                      {editingId === item.id ? (
                        <div className="flex items-center gap-2 flex-1">
                            <input 
                                type="text" 
                                value={editingName} 
                                onChange={(e) => setEditingName(e.target.value)}
                                className="flex-1 px-3 py-1.5 border border-blue-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-200"
                                autoFocus
                            />
                            <button onClick={() => saveEdit(item.id)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg">
                                <Check size={18} />
                            </button>
                            <button onClick={cancelEdit} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">
                                <X size={18} />
                            </button>
                        </div>
                      ) : (
                        <>
                            <div className="flex items-center gap-3">
                                {activeTab === 'materials' && (
                                    <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-xs font-bold text-slate-500">
                                        M
                                    </div>
                                )}
                                <span className="text-slate-700 font-medium">{item.name}</span>
                            </div>

                            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button 
                                    onClick={() => startEdit(item.id, item.name)}
                                    className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Editar"
                                >
                                    <Edit2 size={16} />
                                </button>
                                <button 
                                    onClick={() => removeSettingItem(activeTab, item.id)}
                                    className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Excluir"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        </>
                      )}
                   </div>
                ))
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { User, Role } from '../types';

interface AuthContextType {
  user: User | null;
  login: (role: Role) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children?: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null);

  const login = (role: Role) => {
    // Simulate login
    // Using Blue (2563EB) background for avatars
    setUser({
      id: 'u1',
      name: role === 'admin' ? 'Administrador Geral' : 'Operador de Campo',
      email: role === 'admin' ? 'admin@villaprivilege.com.br' : 'op@villaprivilege.com.br',
      role: role,
      avatar: `https://ui-avatars.com/api/?name=${role}&background=2563EB&color=fff`,
    });
  };

  const logout = () => {
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within an AuthProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

type Theme = 'light' | 'dark';

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider = ({ children }: { children?: ReactNode }) => {
  const [theme, setTheme] = useState<Theme>(() => {
    // Check local storage or system preference
    const saved = localStorage.getItem('theme');
    if (saved === 'dark' || saved === 'light') return saved;
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark';
    return 'light';
  });

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('useTheme must be used within a ThemeProvider');
  return context;
};

import React, { ReactNode } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { DataProvider } from './context/DataContext';
import { ThemeProvider } from './context/ThemeContext';
import { Layout } from './components/ui/Layout';
import { Login } from './components/pages/Login';
import { Dashboard } from './components/pages/Dashboard';
import { TaskList } from './components/pages/TaskList';
import { Settings } from './components/pages/Settings';

const ProtectedRoute = ({ children }: { children?: ReactNode }) => {
  const { user } = useAuth();
  if (!user) {
    return <Login />;
  }
  return <>{children}</>;
};

const AdminRoute = ({ children }: { children?: ReactNode }) => {
  const { user } = useAuth();
  if (user?.role !== 'admin') {
    return <Navigate to="/" replace />;
  }
  return <>{children}</>;
};

const AppContent = () => {
  const { user } = useAuth();

  return (
    <Routes>
      <Route path="/" element={
        <ProtectedRoute>
          <Layout />
        </ProtectedRoute>
      }>
        <Route index element={<Dashboard />} />
        <Route path="tasks" element={<TaskList />} />
        <Route path="settings" element={
          <AdminRoute>
            <Settings />
          </AdminRoute>
        } />
      </Route>
    </Routes>
  );
}

export default function App() {
  return (
    <ThemeProvider>
      <AuthProvider>
        <DataProvider>
          <HashRouter>
             <AppContent />
          </HashRouter>
        </DataProvider>
      </AuthProvider>
    </ThemeProvider>
  );
}

