        </main>
      </div>
    </div>
  );
};

import React from 'react';
import { useData } from '../../context/DataContext';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Legend
} from 'recharts';
import { AlertTriangle, CheckCircle2, Clock, ListFilter } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';

// Tech-X / Villa Privilege Palette
const COLORS = ['#2563eb', '#38bdf8', '#475569', '#6366f1', '#94a3b8', '#cbd5e1'];

export const Dashboard = () => {
  const { tasks, settings } = useData();
  const { theme } = useTheme();

  // Metrics
  const totalTasks = tasks.length;
  const pendingTasks = tasks.filter(t => t.situation === 'Aberto').length;
  const inProgressTasks = tasks.filter(t => t.situation === 'Em Andamento').length;
  const completedTasks = tasks.filter(t => t.situation === 'Concluído').length;
  const highCritTasks = tasks.filter(t => t.criticality === 'Alta' && t.situation !== 'Concluído').length;

  const situationData = settings.situations.map(sit => ({
      name: sit.name,
      value: tasks.filter(t => t.situation === sit.name).length
  })).filter(item => item.value > 0); 

  const knownSituations = settings.situations.map(s => s.name);
  const unknownTasksCount = tasks.filter(t => !knownSituations.includes(t.situation)).length;
  if (unknownTasksCount > 0) {
      situationData.push({ name: 'Outros', value: unknownTasksCount });
  }

  const sectorData = settings.sectors.map(sector => ({
    name: sector.name,
    tarefas: tasks.filter(t => t.sectorId === sector.id).length
  })).filter(d => d.tarefas > 0);

  const StatCard = ({ title, value, icon: Icon, colorClass, subText }: any) => (
    <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-start justify-between hover:shadow-md transition-all">
      <div>
        <p className="text-sm font-medium text-slate-500 dark:text-slate-400 mb-1">{title}</p>
        <h3 className="text-3xl font-bold text-slate-800 dark:text-white">{value}</h3>
        {subText && <p className="text-xs text-slate-400 dark:text-slate-500 mt-2">{subText}</p>}
      </div>
      <div className={`p-3 rounded-xl ${colorClass}`}>
        <Icon size={24} className="text-white" />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Painel de Controle</h2>
           <p className="text-slate-500 dark:text-slate-400">Visão geral do condomínio</p>
        </div>
        <div className="flex gap-2">
           <select className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-600 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500">
             <option>Últimos 30 dias</option>
             <option>Esta semana</option>
             <option>Hoje</option>
           </select>
        </div>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Tarefas Totais" 
          value={totalTasks} 
          icon={ListFilter} 
          colorClass="bg-blue-600" 
          subText="Desde o início"
        />
        <StatCard 
          title="Em Andamento" 
          value={inProgressTasks} 
          icon={Clock} 
          colorClass="bg-sky-500" 
          subText={`${Math.round((inProgressTasks/totalTasks || 0)*100)}% do total`}
        />
        <StatCard 
          title="Concluídas" 
          value={completedTasks} 
          icon={CheckCircle2} 
          colorClass="bg-slate-600" 
          subText="Finalizadas com sucesso"
        />
        <StatCard 
          title="Criticidade Alta" 
          value={highCritTasks} 
          icon={AlertTriangle} 
          colorClass="bg-red-500" 
          subText="Requer atenção imediata"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Situation Distribution */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-6">Status das Tarefas</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={situationData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                  stroke={theme === 'dark' ? '#1e293b' : '#fff'}
                >
                  {situationData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip 
                   contentStyle={{ backgroundColor: theme === 'dark' ? '#1e293b' : '#fff', borderRadius: '8px', border: theme === 'dark' ? '1px solid #334155' : 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', color: theme === 'dark' ? '#fff' : '#334155' }}
                   itemStyle={{ color: theme === 'dark' ? '#e2e8f0' : '#334155' }}
                />
                <Legend verticalAlign="bottom" height={36} wrapperStyle={{ color: theme === 'dark' ? '#94a3b8' : '#64748b' }}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Tasks by Sector */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-6">Tarefas por Setor</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={sectorData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#334155' : '#e2e8f0'} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 12}} />
                <Tooltip 
                   cursor={{fill: theme === 'dark' ? '#334155' : '#f1f5f9'}}
                   contentStyle={{ backgroundColor: theme === 'dark' ? '#1e293b' : '#fff', borderRadius: '8px', border: theme === 'dark' ? '1px solid #334155' : 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', color: theme === 'dark' ? '#fff' : '#334155' }}
                />
                <Bar dataKey="tarefas" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { useAuth } from '../../context/AuthContext';
import { Plus, Search, Filter, Download, MoreVertical, Edit2, Trash2 } from 'lucide-react';
import { TaskFormModal } from '../ui/TaskFormModal';
import { Task } from '../../types';

export const TaskList = () => {
  const { tasks, settings, deleteTask, exportTasksToCSV } = useData();
  const { user } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSituation, setFilterSituation] = useState('Todos');
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  const getResponsibleName = (id: string) => settings.responsibles.find(r => r.id === id)?.name || 'N/A';
  const getSectorName = (id: string) => settings.sectors.find(s => s.id === id)?.name || 'N/A';

  const handleEdit = (task: Task) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setEditingTask(undefined);
    setIsModalOpen(true);
  };

  const filteredTasks = tasks.filter(task => {
    const matchesSearch = task.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          task.location.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterSituation === 'Todos' || task.situation === filterSituation;
    return matchesSearch && matchesFilter;
  });

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Concluído': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300';
      case 'Em Andamento': return 'bg-sky-100 text-sky-700 dark:bg-sky-900/30 dark:text-sky-300';
      case 'Cancelado': return 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300';
      default: return 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300'; // Aberto
    }
  };

  const getCriticalityColor = (crit: string) => {
    switch(crit) {
        case 'Alta': return 'text-red-600 bg-red-50 border-red-100 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/30';
        case 'Média': return 'text-amber-600 bg-amber-50 border-amber-100 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-900/30';
        default: return 'text-slate-600 bg-slate-50 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Tarefas de Manutenção</h2>
          <p className="text-slate-500 dark:text-slate-400">Gerencie todas as ordens de serviço</p>
        </div>
        <div className="flex gap-2">
           <button onClick={exportTasksToCSV} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
              <Download size={18} />
              <span className="hidden sm:inline">Exportar</span>
           </button>
           <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm shadow-blue-200 dark:shadow-none transition-all transform active:scale-95">
              <Plus size={18} />
              <span>Nova Tarefa</span>
           </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
         <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar por título ou local..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-800 dark:text-slate-200 placeholder-slate-400"
            />
         </div>
         <div className="flex items-center gap-2">
            <Filter size={18} className="text-slate-400" />
            <select 
              value={filterSituation}
              onChange={(e) => setFilterSituation(e.target.value)}
              className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-600 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="Todos">Todas as Situações</option>
              <option value="Aberto">Aberto</option>
              <option value="Em Andamento">Em Andamento</option>
              <option value="Concluído">Concluído</option>
              <option value="Cancelado">Cancelado</option>
            </select>
         </div>
      </div>

      {/* Table */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
         <div className="overflow-x-auto">
           <table className="w-full text-left border-collapse">
             <thead>
               <tr className="bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                 <th className="px-6 py-4">ID / Título</th>
                 <th className="px-6 py-4">Setor / Local</th>
                 <th className="px-6 py-4">Responsável</th>
                 <th className="px-6 py-4">Data Chamado</th>
                 <th className="px-6 py-4">Situação</th>
                 <th className="px-6 py-4">Criticidade</th>
                 <th className="px-6 py-4 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredTasks.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="px-6 py-8 text-center text-slate-400 dark:text-slate-500">
                       Nenhuma tarefa encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredTasks.map((task) => (
                    <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                       <td className="px-6 py-4">
                          <div className="font-medium text-slate-800 dark:text-slate-200">{task.title}</div>
                          <div className="text-xs text-slate-400 dark:text-slate-500">{task.id}</div>
                       </td>
                       <td className="px-6 py-4">
                          <div className="text-slate-700 dark:text-slate-300">{getSectorName(task.sectorId)}</div>
                          <div className="text-xs text-slate-400 dark:text-slate-500">{task.location}</div>
                       </td>
                       <td className="px-6 py-4 text-slate-600 dark:text-slate-400">
                          {getResponsibleName(task.responsibleId)}
                       </td>
                       <td className="px-6 py-4 text-slate-600 dark:text-slate-400">
                          {new Date(task.callDate).toLocaleDateString('pt-BR')}
                       </td>
                       <td className="px-6 py-4">
                          <span className={`px-2.5 py-1 rounded-full text-xs font-medium border border-transparent ${getStatusColor(task.situation)}`}>
                             {task.situation}
                          </span>
                       </td>
                       <td className="px-6 py-4">
                          <span className={`px-2.5 py-1 rounded-md text-xs font-medium border ${getCriticalityColor(task.criticality)}`}>
                             {task.criticality}
                          </span>
                       </td>
                       <td className="px-6 py-4 text-right">
                          <div className="flex items-center justify-end gap-2">
                             <button onClick={() => handleEdit(task)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors">
                               <Edit2 size={16} />
                             </button>
                             {user?.role === 'admin' && (
                               <button onClick={() => deleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors">
                                 <Trash2 size={16} />
                               </button>
                             )}
                          </div>
                       </td>
                    </tr>
                  ))
                )}
             </tbody>
           </table>
         </div>
      </div>

      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        initialData={editingTask}
      />
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useData } from '../../context/DataContext';
import { Task, Criticality } from '../../types';
import { X, Save, Calendar, MapPin, CheckSquare, Square } from 'lucide-react';

interface TaskFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialData?: Task;
}

export const TaskFormModal: React.FC<TaskFormModalProps> = ({ isOpen, onClose, initialData }) => {
  const { settings, addTask, updateTask } = useData();

  // Form State
  const [formData, setFormData] = useState<Partial<Task>>({
    title: '',
    sectorId: '',
    serviceId: '',
    towerId: '',
    location: '',
    responsibleId: '',
    situation: settings.situations[0]?.name || 'Aberto',
    criticality: 'Média',
    materials: [],
    callDate: new Date().toISOString().split('T')[0],
    startDate: '',
    endDate: ''
  });

  useEffect(() => {
    if (initialData) {
        setFormData({
            ...initialData,
            callDate: initialData.callDate.split('T')[0],
            startDate: initialData.startDate ? initialData.startDate.split('T')[0] : '',
            endDate: initialData.endDate ? initialData.endDate.split('T')[0] : ''
        });
    } else {
        // Reset for new entry
        setFormData({
            title: '',
            sectorId: settings.sectors[0]?.id || '',
            serviceId: settings.services[0]?.id || '',
            towerId: settings.towers[0]?.id || '',
            location: '',
            responsibleId: settings.responsibles[0]?.id || '',
            situation: settings.situations[0]?.name || 'Aberto',
            criticality: 'Média',
            materials: [],
            callDate: new Date().toISOString().split('T')[0],
            startDate: '',
            endDate: ''
        });
    }
  }, [initialData, isOpen, settings]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleMaterialToggle = (materialId: string) => {
    setFormData(prev => {
        const current = prev.materials || [];
        if (current.includes(materialId)) {
            return { ...prev, materials: current.filter(id => id !== materialId) };
        } else {
            return { ...prev, materials: [...current, materialId] };
        }
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Basic validation
    if(!formData.title || !formData.location) {
        alert("Preencha os campos obrigatórios (Título e Localização)");
        return;
    }

    if (initialData) {
        updateTask(initialData.id, formData);
    } else {
        addTask(formData as Omit<Task, 'id' | 'createdAt'>);
    }
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-fade-in">
       <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl w-full max-w-4xl max-h-[90vh] overflow-y-auto border border-slate-200 dark:border-slate-700">
          {/* Header */}
          <div className="sticky top-0 z-10 bg-white dark:bg-slate-800 border-b border-slate-100 dark:border-slate-700 px-6 py-4 flex items-center justify-between">
             <h3 className="text-xl font-bold text-slate-800 dark:text-white">
                {initialData ? 'Editar Tarefa' : 'Nova Ordem de Manutenção'}
             </h3>
             <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-full transition-colors">
                <X size={24} />
             </button>
          </div>

          <form onSubmit={handleSubmit} className="p-6 space-y-8">
             {/* Main Info Group */}
             <div className="space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Título da Tarefa *</label>
                        <input 
                           type="text" 
                           name="title" 
                           value={formData.title} 
                           onChange={handleChange}
                           className="w-full px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                           placeholder="Ex: Manutenção Preventiva Motor A"
                        />
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Localização *</label>
                        <div className="relative">
                            <MapPin size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input 
                            type="text" 
                            name="location" 
                            value={formData.location} 
                            onChange={handleChange}
                            className="w-full pl-10 pr-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                            placeholder="Ex: Sala de Máquinas 02"
                            />
                        </div>
                    </div>
                 </div>
             </div>

             <div className="border-t border-slate-100 dark:border-slate-700 pt-6">
                <h4 className="text-sm uppercase tracking-wide text-slate-500 dark:text-slate-400 font-semibold mb-4">Detalhes Operacionais</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Setor</label>
                        <select name="sectorId" value={formData.sectorId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none">
                           {settings.sectors.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tipo de Serviço</label>
                        <select name="serviceId" value={formData.serviceId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none">
                           {settings.services.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Torre</label>
                        <select name="towerId" value={formData.towerId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none">
                           {settings.towers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Responsável Técnico</label>
                        <select name="responsibleId" value={formData.responsibleId} onChange={handleChange} className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 outline-none">
                           {settings.responsibles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
             </div>

