export const DataProvider = ({ children }: { children?: ReactNode }) => {
  const [tasks, setTasks] = useState<Task[]>(initialTasks);
  const [visits, setVisits] = useState<Visit[]>(initialVisits);
  const [schedule, setSchedule] = useState<ScheduleItem[]>(initialSchedule);
  const [paintingProjects, setPaintingProjects] = useState<PaintingProject[]>(initialPainting);
  const [purchases, setPurchases] = useState<PurchaseRequest[]>(initialPurchases);
  const [settings, setSettings] = useState<SettingsState>(initialSettings);

  // --- TASKS ---
  const addTask = (newTask: Omit<Task, 'id' | 'createdAt'>) => {
    const task: Task = {
      ...newTask,
      id: `T-${Math.floor(1000 + Math.random() * 9000)}`,
      createdAt: new Date().toISOString(),
    };
    setTasks((prev) => [task, ...prev]);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks((prev) => prev.map((t) => (t.id === id ? { ...t, ...updates } : t)));
  };

  const deleteTask = (id: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  // --- VISITS ---
  const addVisit = (item: Omit<Visit, 'id'>) => {
     setVisits(prev => [{...item, id: Math.random().toString(36).substr(2, 9)}, ...prev]);
  };
  const updateVisit = (id: string, updates: Partial<Visit>) => {
     setVisits(prev => prev.map(v => v.id === id ? { ...v, ...updates } : v));
  };
  const deleteVisit = (id: string) => {
     setVisits(prev => prev.filter(v => v.id !== id));
  };

  // --- SCHEDULE ---
  const updateSchedule = (id: string, updates: Partial<ScheduleItem>) => {
      setSchedule(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  };

  // --- PAINTING ---
  const addPaintingProject = (item: Omit<PaintingProject, 'id'>) => {
      setPaintingProjects(prev => [{...item, id: Math.random().toString(36).substr(2, 9)}, ...prev]);
  };
  const updatePaintingProject = (id: string, updates: Partial<PaintingProject>) => {
      setPaintingProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates } : p));
  };
  const deletePaintingProject = (id: string) => {
      setPaintingProjects(prev => prev.filter(p => p.id !== id));
  };

  // --- PURCHASES ---
  const addPurchase = (item: Omit<PurchaseRequest, 'id'>) => {
      setPurchases(prev => [{...item, id: Math.random().toString(36).substr(2, 9)}, ...prev]);
  };
  const updatePurchase = (id: string, updates: Partial<PurchaseRequest>) => {
      setPurchases(prev => prev.map(p => p.id === id ? { ...p, ...updates } : p));
  };
  const deletePurchase = (id: string) => {
      setPurchases(prev => prev.filter(p => p.id !== id));
  };

  // --- SETTINGS ---
  const addSettingItem = (category: keyof SettingsState, name: string) => {
    const newItem: CatalogItem = {
      id: Math.random().toString(36).substr(2, 9),
      name,
    };
    setSettings((prev) => ({
      ...prev,
      [category]: [...prev[category], newItem],
    }));
  };

  const updateSettingItem = (category: keyof SettingsState, id: string, newName: string) => {
    setSettings((prev) => ({
      ...prev,
      [category]: prev[category].map(item => 
        item.id === id ? { ...item, name: newName } : item
      ),
    }));
  };

  const removeSettingItem = (category: keyof SettingsState, id: string) => {
    setSettings((prev) => ({
      ...prev,
      [category]: prev[category].filter((item) => item.id !== id),
    }));
  };

  const exportTasksToCSV = () => {
    const headers = ['ID', 'Serviço', 'Torre', 'Local', 'Situação', 'Criticidade', 'Data Chamado', 'Materiais'];
    const findName = (list: CatalogItem[], id: string) => list.find(i => i.id === id)?.name || id;

    const rows = tasks.map(t => {
        const service = findName(settings.services, t.serviceId);
        const tower = findName(settings.towers, t.towerId);
        const materials = t.materials.map(mId => findName(settings.materials, mId)).join('; ');

        return [t.id, service, tower, t.location, t.situation, t.criticality, t.callDate, materials];
    });

    let csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(",") + "\n" 
        + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "tarefas_villaprivilege.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <DataContext.Provider value={{ 
        tasks, visits, schedule, paintingProjects, purchases, settings, 
        addTask, updateTask, deleteTask, 
        addVisit, updateVisit, deleteVisit,
        updateSchedule,
        addPaintingProject, updatePaintingProject, deletePaintingProject,
        addPurchase, updatePurchase, deletePurchase,
        addSettingItem, updateSettingItem, removeSettingItem, 
        exportTasksToCSV 
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useData must be used within a DataProvider');
  return context;
};

