      {/* Table */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden w-full">
         <div className="overflow-x-auto">
           {/* FORCE Min Width to prevent squishing columns */}
           <table className="w-full text-left border-collapse min-w-[1200px]">
             <thead>
               <tr className="bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                 <th className="px-4 py-4 min-w-[200px]">Serviço / Torre</th>
                 <th className="px-4 py-4 whitespace-nowrap">Abertura</th>
                 {/* Increased width for Execution to ensure dates are visible */}
                 <th className="px-4 py-4 min-w-[200px]">Execução</th>
                 <th className="px-4 py-4">Mat. Disp.</th>
                 <th className="px-4 py-4 min-w-[180px]">Local / Setor</th>
                 <th className="px-4 py-4 min-w-[150px]">Responsável</th>
                 <th className="px-4 py-4">Situação</th>
                 <th className="px-4 py-4 text-center">Criticidade</th>
                 <th className="px-4 py-4 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredTasks.length === 0 ? (
                  <tr>
                    <td colSpan={9} className="px-4 py-8 text-center text-slate-400 dark:text-slate-500">
                       Nenhuma tarefa encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredTasks.map((task) => {
                      const materialNames = getMaterialNames(task.materials);
                      return (
                        <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                        <td className="px-4 py-4">
                            <div className="font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2">
                                <Wrench size={14} className="text-blue-500 shrink-0" />
                                {getServiceName(task.serviceId)}
                            </div>
                            <div className="text-sm font-semibold text-blue-600 dark:text-blue-400 mt-1 pl-6">
                                {getTowerName(task.towerId)}
                            </div>
                        </td>
                        <td className="px-4 py-4 whitespace-nowrap">
                             <div className="text-slate-700 dark:text-slate-300 font-medium bg-slate-100 dark:bg-slate-900 px-2 py-1 rounded inline-block text-xs border border-slate-200 dark:border-slate-700">
                                {formatDate(task.callDate)}
                             </div>
                        </td>
                         <td className="px-4 py-4">
                            <div className="flex flex-col gap-2 text-xs">
                                <div className="flex items-center gap-2 whitespace-nowrap" title="Data de Início">
                                    <span className="font-bold text-emerald-600 dark:text-emerald-400 w-10">Início:</span> 
                                    <span className="text-slate-700 dark:text-slate-300 font-mono bg-emerald-50 dark:bg-emerald-900/20 px-1.5 py-0.5 rounded border border-emerald-100 dark:border-emerald-900/30">
                                        {formatDate(task.startDate)}
                                    </span>
                                </div>
                                <div className="flex items-center gap-2 whitespace-nowrap" title="Data de Término">
                                    <span className="font-bold text-slate-500 dark:text-slate-400 w-10">Fim:</span> 
                                    <span className="text-slate-700 dark:text-slate-300 font-mono bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded border border-slate-200 dark:border-slate-700">
                                        {formatDate(task.endDate)}
                                    </span>
                                </div>
                            </div>
                        </td>
                        <td className="px-4 py-4">
                            {materialNames ? (
                                <div className="text-xs text-slate-600 dark:text-slate-400 max-w-[120px] leading-tight group relative cursor-help">
                                    <span className="font-bold text-emerald-600 dark:text-emerald-400">SIM</span>
                                    <span className="ml-1 text-[10px] text-slate-400 underline">ver</span>
                                    {/* Tooltip simple approach */}
                                    <div className="absolute hidden group-hover:block left-0 bottom-full mb-1 bg-slate-800 text-white text-[10px] p-2 rounded shadow-lg z-10 w-32">
                                        {materialNames}
                                    </div>
                                </div>
                            ) : (
                                <span className="text-xs font-bold text-slate-400 dark:text-slate-500">NÃO</span>
                            )}
                        </td>

                        <td className="px-4 py-4">
                            <div className="text-slate-700 dark:text-slate-300 font-medium">{task.location}</div>
                            <div className="text-xs text-slate-400 dark:text-slate-500">{getSectorName(task.sectorId)}</div>
                        </td>
                        <td className="px-4 py-4 text-slate-600 dark:text-slate-400 text-xs">
                            {getResponsibleName(task.responsibleId)}
                        </td>
                        <td className="px-4 py-4 whitespace-nowrap">
                            <span className={`px-2.5 py-1 rounded-full text-xs font-medium border border-transparent ${getStatusColor(task.situation)}`}>
                                {task.situation}
                            </span>
                        </td>
                        <td className="px-4 py-4 text-center">
