import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { useAuth } from '../../context/AuthContext';
import { Plus, Search, Filter, Download, Edit2, Trash2, Wrench, Upload, Eraser, Calendar } from 'lucide-react';
import { TaskFormModal } from '../ui/TaskFormModal';
import { Task } from '../../types';

export const TaskList = () => {
  const { tasks, settings, deleteTask, exportTasksToCSV, importDataFromCSV } = useData();
  const { user } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSituation, setFilterSituation] = useState('Todos');
  const [dateFilter, setDateFilter] = useState<'all' | 'week' | 'month'>('all');

  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  const getResponsibleName = (id: string) => settings.responsibles.find(r => r.id === id)?.name || 'N/A';
  const getSectorName = (id: string) => settings.sectors.find(s => s.id === id)?.name || 'N/A';
  const getServiceName = (id: string) => settings.services.find(s => s.id === id)?.name || 'Serviço';
  const getTowerName = (id: string) => settings.towers.find(t => t.id === id)?.name || 'Torre';

  const getMaterialNames = (ids: string[]) => {
      if (!ids || ids.length === 0) return null;
      return ids.map(id => settings.materials.find(m => m.id === id)?.name).filter(Boolean).join(', ');
  };

  const handleEdit = (task: Task) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setEditingTask(undefined);
    setIsModalOpen(true);
  };

  const handleClearFilters = () => {
      setSearchTerm('');
      setFilterSituation('Todos');
      setDateFilter('all');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          const content = event.target?.result as string;
          const result = importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  const filteredTasks = tasks.filter(task => {
    // 1. Search Filter
    const serviceName = getServiceName(task.serviceId).toLowerCase();
    const towerName = getTowerName(task.towerId).toLowerCase();
    const matchesSearch = task.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          task.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          serviceName.includes(searchTerm.toLowerCase()) ||
                          towerName.includes(searchTerm.toLowerCase());

    // 2. Situation Filter
    const matchesSituation = filterSituation === 'Todos' || task.situation === filterSituation;

    // 3. Date Filter (Based on Call Date)
    let matchesDate = true;
    if (dateFilter !== 'all') {
        const taskDate = new Date(task.callDate);
        const now = new Date();

        if (dateFilter === 'month') {
            matchesDate = taskDate.getMonth() === now.getMonth() && taskDate.getFullYear() === now.getFullYear();
        } else if (dateFilter === 'week') {
            const startOfWeek = new Date(now);
            startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday
            startOfWeek.setHours(0, 0, 0, 0);

            const endOfWeek = new Date(startOfWeek);
            endOfWeek.setDate(startOfWeek.getDate() + 6); // Saturday
            endOfWeek.setHours(23, 59, 59, 999);

            matchesDate = taskDate >= startOfWeek && taskDate <= endOfWeek;
        }
    }

    return matchesSearch && matchesSituation && matchesDate;
  });

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Concluído': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300';
      case 'Em Andamento': return 'bg-sky-100 text-sky-700 dark:bg-sky-900/30 dark:text-sky-300';
      case 'Cancelado': return 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300';
      default: return 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300'; // Aberto
    }
  };

  const getCriticalityColor = (crit: string) => {
    switch(crit) {
        case 'Alta': return 'text-red-600 bg-red-50 border-red-100 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/30';
        case 'Média': return 'text-amber-600 bg-amber-50 border-amber-100 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-900/30';
        default: return 'text-slate-600 bg-slate-50 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
    }
  };

  // Short Date Formatter (DD/MM)
  const formatShortDate = (dateString?: string) => {
      if (!dateString || dateString.trim() === '') return '-';

      try {
        // Handle ISO or manual input
        const date = new Date(dateString);
        if (isNaN(date.getTime())) {
             // Try split if DD/MM/YYYY
             if(dateString.includes('/')) {
                 const parts = dateString.split('/');
                 if(parts.length >= 2) return `${parts[0]}/${parts[1]}`;
             }
             return '-';
        }
        return date.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
      } catch (e) {
          return '-';
      }
  };

  const hasActiveFilters = searchTerm !== '' || filterSituation !== 'Todos' || dateFilter !== 'all';

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Tarefas de Manutenção</h2>
          <p className="text-slate-500 dark:text-slate-400">Gerencie todas as ordens de serviço</p>
        </div>
        <div className="flex gap-2">
           <label className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors cursor-pointer">
              <Upload size={18} />
              <span className="hidden sm:inline">Importar</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
           </label>
           <button onClick={exportTasksToCSV} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
              <Download size={18} />
              <span className="hidden sm:inline">Exportar</span>
           </button>
           <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm shadow-blue-200 dark:shadow-none transition-all transform active:scale-95">
              <Plus size={18} />
              <span>Nova Tarefa</span>
           </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col xl:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
         <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar por serviço, torre, local..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-800 dark:text-slate-200 placeholder-slate-400"
            />
         </div>
         <div className="flex flex-wrap items-center gap-2">

            {/* Situation Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Filter size={16} className="text-slate-400" />
                <select 
                value={filterSituation}
                onChange={(e) => setFilterSituation(e.target.value)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="Todos">Todas as Situações</option>
                {settings.situations.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
            </div>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Calendar size={16} className="text-slate-400" />
                <select 
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value as any)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="all">Todo o Período</option>
                <option value="week">Esta Semana</option>
                <option value="month">Este Mês</option>
                </select>
            </div>

            {/* Clear Button (Top) */}
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors border border-transparent hover:border-red-100"
                >
                    <Eraser size={16} />
                    Limpar
                </button>
            )}
         </div>
      </div>

      {/* Table Container */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden flex flex-col">
         <div className="overflow-x-auto">
           <table className="w-full text-left border-collapse min-w-[1000px]">
             <thead>
               <tr className="bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                 <th className="px-3 py-3 w-[25%]">Serviço / Torre</th>
                 <th className="px-3 py-3 w-[15%]">Datas (Ab/In/Fi)</th>
                 <th className="px-3 py-3 w-[15%]">Local / Setor</th>
                 <th className="px-3 py-3">Responsável</th>
                 <th className="px-3 py-3 text-center">Mat.</th>
                 <th className="px-3 py-3 text-center">Situação</th>
                 <th className="px-3 py-3 text-center">Crit.</th>
                 <th className="px-3 py-3 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredTasks.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="px-4 py-8 text-center text-slate-400 dark:text-slate-500">
                       Nenhuma tarefa encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredTasks.map((task) => {
                      const materialNames = getMaterialNames(task.materials);
                      return (
                        <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                            {/* Service / Tower */}
                            <td className="px-3 py-3 align-top">
                                <div className="font-bold text-slate-800 dark:text-slate-200 flex items-start gap-2 text-sm">
                                    <Wrench size={14} className="text-blue-500 shrink-0 mt-0.5" />
                                    <span className="leading-tight">{getServiceName(task.serviceId)}</span>
                                </div>
                                <div className="text-xs font-semibold text-blue-600 dark:text-blue-400 mt-1 pl-6">
                                    {getTowerName(task.towerId)}
                                </div>
                            </td>

                            {/* Consolidated Dates */}
                            <td className="px-3 py-3 align-top">
                                <div className="flex flex-col gap-0.5 text-xs font-mono">
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-slate-400">Ab:</span> 
                                        {formatShortDate(task.callDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-emerald-600 dark:text-emerald-500">In:</span> 
                                        {formatShortDate(task.startDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-indigo-500">Fi:</span> 
                                        {formatShortDate(task.endDate)}
                                    </div>
                                </div>
                            </td>

                            {/* Location / Sector */}
                            <td className="px-3 py-3 align-top">
                                <div className="text-slate-700 dark:text-slate-300 font-medium text-sm leading-tight truncate max-w-[150px]" title={task.location}>
                                    {task.location}
                                </div>
                                <div className="text-xs text-slate-400 dark:text-slate-500 mt-0.5">
                                    {getSectorName(task.sectorId)}
                                </div>
                            </td>

                            {/* Responsible */}
                            <td className="px-3 py-3 align-top text-slate-600 dark:text-slate-400 text-xs">
                                <div className="truncate max-w-[120px]" title={getResponsibleName(task.responsibleId)}>
                                    {getResponsibleName(task.responsibleId)}
                                </div>
                            </td>

                            {/* Materials */}
                            <td className="px-3 py-3 text-center align-top">
                                {materialNames ? (
                                    <div className="group relative cursor-help flex justify-center">
                                        <span className="w-5 h-5 flex items-center justify-center rounded bg-emerald-100 text-emerald-700 text-[10px] font-bold">
                                            Sim
                                        </span>
                                        <div className="absolute hidden group-hover:block right-0 top-full mt-1 bg-slate-800 text-white text-[10px] p-2 rounded shadow-lg z-10 w-32 text-left">
                                            {materialNames}
                                        </div>
                                    </div>
                                ) : (
                                    <span className="text-slate-300 dark:text-slate-600 text-lg leading-none">-</span>
                                )}
                            </td>

                            {/* Situation */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold border border-transparent ${getStatusColor(task.situation)}`}>
                                    {task.situation}
                                </span>
                            </td>

                            {/* Criticality */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2 py-0.5 rounded-md text-[10px] font-bold border ${getCriticalityColor(task.criticality)}`}>
                                    {task.criticality}
                                </span>
                            </td>

                            {/* Actions */}
                            <td className="px-3 py-3 text-right align-top">
                                <div className="flex items-center justify-end gap-1">
                                    <button onClick={() => handleEdit(task)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" title="Editar">
                                    <Edit2 size={16} />
                                    </button>
                                    {user?.role === 'admin' && (
                                    <button onClick={() => deleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" title="Excluir">
                                        <Trash2 size={16} />
                                    </button>
                                    )}
                                </div>
                            </td>
                        </tr>
                      );
                  })
                )}
             </tbody>
           </table>
         </div>

         {/* Table Footer with Filter Reset */}
         <div className="border-t border-slate-100 dark:border-slate-700 p-3 bg-slate-50 dark:bg-slate-700/20 flex items-center justify-between">
            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                Total: {filteredTasks.length} {filteredTasks.length === 1 ? 'tarefa encontrada' : 'tarefas encontradas'}
            </span>
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-1 text-xs font-bold text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20 px-3 py-1.5 rounded transition-colors"
                >
                    <Eraser size={14} />
                    Limpar Tudo
                </button>
            )}
         </div>
      </div>

      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        initialData={editingTask}
      />
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useData } from '../../context/DataContext';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Legend
} from 'recharts';
import { AlertTriangle, CheckCircle2, Clock, ListFilter, CalendarDays, Users, PaintBucket, ShoppingCart, ArrowRight } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { Link } from 'react-router-dom';

// Tech-X / Villa Privilege Palette
const COLORS = ['#2563eb', '#38bdf8', '#475569', '#6366f1', '#94a3b8', '#cbd5e1'];

export const Dashboard = () => {
  const { tasks, settings, visits, schedule, paintingProjects, purchases } = useData();
  const { theme } = useTheme();

  // State for date filter: '30' | '7' | '1' | 'all'
  const [dateRange, setDateRange] = useState('30');

  // --- Filter Logic ---
  const filteredTasks = useMemo(() => {
    if (dateRange === 'all') return tasks;

    const now = new Date();
    // Reset time to start of day for accurate comparison
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    return tasks.filter(task => {
        if (!task.callDate) return false;

        // Handle ISO or manual date strings
        let taskDate = new Date(task.callDate);
        if (isNaN(taskDate.getTime())) {
             // Try parsing DD/MM/YYYY manually if needed, or assume invalid
             if (task.callDate.includes('/')) {
                 const [d, m, y] = task.callDate.split('/');
                 taskDate = new Date(Number(y), Number(m) - 1, Number(d));
             } else {
                 return false;
             }
        }
        // Normalize task date to start of day
        taskDate.setHours(0, 0, 0, 0);

        if (dateRange === '1') {
            // Today
            return taskDate.getTime() === today.getTime();
        } else if (dateRange === '7') {
            // This Week (Start from Sunday)
            const startOfWeek = new Date(today);
            startOfWeek.setDate(today.getDate() - today.getDay());
            return taskDate >= startOfWeek;
        } else if (dateRange === '30') {
            // Last 30 Days
            const thirtyDaysAgo = new Date(today);
            thirtyDaysAgo.setDate(today.getDate() - 30);
            return taskDate >= thirtyDaysAgo;
        }
        return true;
    });
  }, [tasks, dateRange]);

  // --- Metrics Calculation (Based on filteredTasks) ---
  const totalTasks = filteredTasks.length;
  const inProgressTasks = filteredTasks.filter(t => t.situation === 'Em Andamento').length;
  const completedTasks = filteredTasks.filter(t => t.situation === 'Concluído').length;
  const highCritTasks = filteredTasks.filter(t => t.criticality === 'Alta' && t.situation !== 'Concluído').length;

  const situationData = settings.situations.map(sit => ({
      name: sit.name,
      value: filteredTasks.filter(t => t.situation === sit.name).length
  })).filter(item => item.value > 0); 

  const knownSituations = settings.situations.map(s => s.name);
  const unknownTasksCount = filteredTasks.filter(t => !knownSituations.includes(t.situation)).length;
  if (unknownTasksCount > 0) {
      situationData.push({ name: 'Outros', value: unknownTasksCount });
  }

  const sectorData = settings.sectors.map(sector => ({
    name: sector.name,
    tarefas: filteredTasks.filter(t => t.sectorId === sector.id).length
  })).filter(d => d.tarefas > 0);

  // --- Helper Logic for Bottom Section ---

  // 1. Schedule Today
  const days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  const dayKey = days[new Date().getDay()];
  const todaySchedule = schedule.map(item => ({
      shift: item.shift,
      task: (item as any)[dayKey] || '-' // Accessing dynamic key safely
  })).filter(i => i.task !== '-' && i.task !== '');

  // 2. Recent Visits (Last 3)
  const recentVisits = [...visits].reverse().slice(0, 3);

  // 3. Active Painting Projects
  const activePainting = paintingProjects.slice(0, 3);

  // 4. Pending Purchases
  const pendingPurchases = purchases.filter(p => !p.approvalDate).slice(0, 3);


  const StatCard = ({ title, value, icon: Icon, colorClass, subText }: any) => (
    <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex items-start justify-between hover:shadow-md transition-all">
      <div>
        <p className="text-sm font-medium text-slate-500 dark:text-slate-400 mb-1">{title}</p>
        <h3 className="text-3xl font-bold text-slate-800 dark:text-white">{value}</h3>
        {subText && <p className="text-xs text-slate-400 dark:text-slate-500 mt-2">{subText}</p>}
      </div>
      <div className={`p-3 rounded-xl ${colorClass}`}>
        <Icon size={24} className="text-white" />
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Painel de Controle</h2>
           <p className="text-slate-500 dark:text-slate-400">Visão geral do condomínio</p>
        </div>
        <div className="flex gap-2">
           <select 
             value={dateRange}
             onChange={(e) => setDateRange(e.target.value)}
             className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-600 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500"
           >
             <option value="30">Últimos 30 dias</option>
             <option value="7">Esta semana</option>
             <option value="1">Hoje</option>
             <option value="all">Todo o período</option>
           </select>
        </div>
      </div>

      {/* Top KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Tarefas no Período" 
          value={totalTasks} 
          icon={ListFilter} 
          colorClass="bg-blue-600" 
          subText={dateRange === 'all' ? 'Histórico completo' : 'Filtrado por data'}
        />
        <StatCard 
          title="Em Andamento" 
          value={inProgressTasks} 
          icon={Clock} 
          colorClass="bg-sky-500" 
          subText={totalTasks > 0 ? `${Math.round((inProgressTasks/totalTasks)*100)}% do período` : '0%'}
        />
        <StatCard 
          title="Concluídas" 
          value={completedTasks} 
          icon={CheckCircle2} 
          colorClass="bg-slate-600" 
          subText="Finalizadas com sucesso"
        />
        <StatCard 
          title="Criticidade Alta" 
          value={highCritTasks} 
          icon={AlertTriangle} 
          colorClass="bg-red-500" 
          subText="Requer atenção imediata"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Situation Distribution */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-6">Status das Tarefas</h3>
          <div className="h-64 w-full">
            {situationData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                    <Pie
                    data={situationData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    fill="#8884d8"
                    paddingAngle={5}
                    dataKey="value"
                    stroke={theme === 'dark' ? '#1e293b' : '#fff'}
                    >
                    {situationData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                    </Pie>
                    <Tooltip 
                    contentStyle={{ backgroundColor: theme === 'dark' ? '#1e293b' : '#fff', borderRadius: '8px', border: theme === 'dark' ? '1px solid #334155' : 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', color: theme === 'dark' ? '#fff' : '#334155' }}
                    itemStyle={{ color: theme === 'dark' ? '#e2e8f0' : '#334155' }}
                    />
                    <Legend verticalAlign="bottom" height={36} wrapperStyle={{ color: theme === 'dark' ? '#94a3b8' : '#64748b' }}/>
                </PieChart>
                </ResponsiveContainer>
            ) : (
                <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                    Sem dados para o período selecionado.
                </div>
            )}
          </div>
        </div>

        {/* Tasks by Sector */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
          <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-6">Tarefas por Setor</h3>
          <div className="h-64 w-full">
            {sectorData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                <BarChart data={sectorData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#334155' : '#e2e8f0'} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 12}} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: theme === 'dark' ? '#94a3b8' : '#64748b', fontSize: 12}} />
                    <Tooltip 
                    cursor={{fill: theme === 'dark' ? '#334155' : '#f1f5f9'}}
                    contentStyle={{ backgroundColor: theme === 'dark' ? '#1e293b' : '#fff', borderRadius: '8px', border: theme === 'dark' ? '1px solid #334155' : 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', color: theme === 'dark' ? '#fff' : '#334155' }}
                    />
                    <Bar dataKey="tarefas" fill="#2563eb" radius={[4, 4, 0, 0]} barSize={40} />
                </BarChart>
                </ResponsiveContainer>
            ) : (
                <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                    Sem dados para o período selecionado.
                </div>
            )}
          </div>
        </div>
      </div>

      {/* --- OPERATIONAL SUMMARY SECTION --- */}
      <div>
        <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-4 flex items-center gap-2">
            Resumo Operacional
            <div className="h-px bg-slate-200 dark:bg-slate-700 flex-1 ml-4"></div>
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">

            {/* Card: Visitas Recentes */}
            <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200 font-semibold">
                        <Users size={18} className="text-blue-500" />
                        <h4>Visitas Recentes</h4>
                    </div>
                    <Link to="/visits" className="text-xs text-blue-600 hover:text-blue-700 dark:text-blue-400 flex items-center gap-1">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                    {recentVisits.length === 0 ? (
                        <p className="text-sm text-slate-400 italic">Nenhuma visita recente.</p>
                    ) : (
                        recentVisits.map(v => (
                            <div key={v.id} className="flex items-center justify-between text-sm p-2 bg-slate-50 dark:bg-slate-700/30 rounded-lg">
                                <div>
                                    <p className="font-medium text-slate-800 dark:text-white">{v.unit} - {v.tower}</p>
                                    <p className="text-xs text-slate-500 dark:text-slate-400">{v.situation}</p>
                                </div>
                                <span className={`text-[10px] px-2 py-0.5 rounded-full ${v.status === 'Pendente' ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'}`}>
                                    {v.status}
                                </span>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Card: Cronograma Hoje */}
            <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200 font-semibold">
                        <CalendarDays size={18} className="text-emerald-500" />
                        <h4>Agenda de Hoje</h4>
                    </div>
                    <Link to="/schedule" className="text-xs text-blue-600 hover:text-blue-700 dark:text-blue-400 flex items-center gap-1">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                    {todaySchedule.length === 0 ? (
                         <p className="text-sm text-slate-400 italic">Sem atividades agendadas para hoje.</p>
                    ) : (
                        todaySchedule.map((s, idx) => (
                            <div key={idx} className="flex items-start gap-3 text-sm p-2 bg-slate-50 dark:bg-slate-700/30 rounded-lg border-l-2 border-emerald-400">
                                <div className="flex-1">
                                    <p className="font-bold text-slate-800 dark:text-white uppercase text-xs mb-0.5">{s.shift}</p>
                                    <p className="text-slate-600 dark:text-slate-300 line-clamp-2">{s.task}</p>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Card: Pintura em Andamento */}
            <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200 font-semibold">
                        <PaintBucket size={18} className="text-indigo-500" />
                        <h4>Pintura</h4>
                    </div>
                    <Link to="/painting" className="text-xs text-blue-600 hover:text-blue-700 dark:text-blue-400 flex items-center gap-1">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                    {activePainting.length === 0 ? (
                        <p className="text-sm text-slate-400 italic">Nenhum projeto de pintura listado.</p>
                    ) : (
                        activePainting.map(p => (
                            <div key={p.id} className="text-sm p-2 border-b border-slate-100 dark:border-slate-700 last:border-0">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-medium text-slate-800 dark:text-white">{p.local}</span>
                                    <span className={`text-[10px] px-1.5 rounded border ${p.criticality === 'Alta' ? 'bg-red-50 text-red-600 border-red-100' : 'bg-slate-50 text-slate-500 border-slate-200'}`}>{p.criticality}</span>
                                </div>
                                <p className="text-xs text-slate-500 dark:text-slate-400">{p.tower}</p>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Card: Compras Pendentes */}
            <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 flex flex-col">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-slate-700 dark:text-slate-200 font-semibold">
                        <ShoppingCart size={18} className="text-orange-500" />
                        <h4>Solicitações Pendentes</h4>
                    </div>
                    <Link to="/purchases" className="text-xs text-blue-600 hover:text-blue-700 dark:text-blue-400 flex items-center gap-1">Ver tudo <ArrowRight size={12}/></Link>
                </div>
                <div className="space-y-3 flex-1">
                     {pendingPurchases.length === 0 ? (
                        <div className="h-full flex items-center justify-center text-center">
                            <p className="text-xs text-slate-400 bg-slate-50 dark:bg-slate-700/50 py-2 px-4 rounded-full">Tudo em dia!</p>
                        </div>
                    ) : (
                        pendingPurchases.map(req => (
                            <div key={req.id} className="flex items-center justify-between text-sm p-2 bg-orange-50 dark:bg-orange-900/10 rounded-lg border border-orange-100 dark:border-orange-900/30">
                                <div>
                                    <div className="flex items-center gap-2">
                                        <span className="font-bold text-slate-800 dark:text-white">{req.quantity}x</span>
                                        <span className="text-slate-700 dark:text-slate-200 truncate max-w-[100px]">{req.description}</span>
                                    </div>
                                    <p className="text-[10px] text-slate-500 uppercase mt-0.5">{req.local}</p>
                                </div>
                                <div className="text-right">
                                    <p className="text-[10px] font-medium text-orange-600 dark:text-orange-400">Aguardando</p>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

