export const Settings = () => {
  const { settings, addSettingItem, updateSettingItem, removeSettingItem, importDataFromCSV, clearAllData } = useData();
  const [activeTab, setActiveTab] = useState<keyof SettingsState | 'import'>('towers');
  const [newItemName, setNewItemName] = useState('');

  // Import State
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [importStatus, setImportStatus] = useState<{success?: boolean; message?: string; details?: string} | null>(null);
  const [isConfirmingClear, setIsConfirmingClear] = useState(false);

  // State for handling inline editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemName.trim() && activeTab !== 'import') {
      addSettingItem(activeTab as keyof SettingsState, newItemName);
      setNewItemName('');
    }
  };

  const startEdit = (id: string, currentName: string) => {
    setEditingId(id);
    setEditingName(currentName);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditingName('');
  };

  const saveEdit = (id: string) => {
    if (editingName.trim()) {
      updateSettingItem(activeTab as keyof SettingsState, id, editingName);
      setEditingId(null);
      setEditingName('');
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          const content = event.target?.result as string;
          const result = importDataFromCSV(content);

          if (result.success) {
              setImportStatus({
                  success: true,
                  message: 'Importação Concluída!',
                  details: `Foram importados ${result.count} itens para a seção: ${translateType(result.type)}`
              });
          } else {
              setImportStatus({
                  success: false,
                  message: 'Falha na Importação',
                  details: result.message
              });
          }
          // Reset input
          if (fileInputRef.current) fileInputRef.current.value = '';
      };
      reader.readAsText(file);
  };

  const handleClearData = async () => {
      await clearAllData();
      setIsConfirmingClear(false);
      setImportStatus({
          success: true,
          message: 'Banco de Dados Limpo',
          details: 'Todos os registros de tarefas, visitas, compras e cronogramas foram removidos.'
      });
  };

  const translateType = (type?: string) => {
      switch(type) {
          case 'visits': return 'Visitas Técnicas';
          case 'tasks': return 'Tarefas de Manutenção';
          case 'painting': return 'Projetos de Pintura';
          case 'purchases': return 'Compras / Almoxarifado';
          case 'weekly_schedule': return 'Cronograma Semanal';
          case 'monthly_schedule': return 'Cronograma Mensal';
          default: return 'Geral';
      }
  };

  const currentItems = activeTab !== 'import' ? settings[activeTab as keyof SettingsState] : [];

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Configurações do Sistema</h2>
        <p className="text-slate-500 dark:text-slate-400">Gerencie todos os cadastros auxiliares do Villa Privilege</p>
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        {/* Sidebar Navigation for Settings */}
        <div className="w-full lg:w-64 flex flex-col gap-2">
           {TABS.map(tab => (
               <button
                 key={tab.id}
                 onClick={() => {
                   setActiveTab(tab.id as any);
                   setEditingId(null);
                   setImportStatus(null);
                   setIsConfirmingClear(false);
                 }}
                 className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    activeTab === tab.id 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 dark:shadow-none' 
                    : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700 border border-transparent hover:border-slate-200 dark:hover:border-slate-700'
                 }`}
               >
                 <tab.icon size={18} />
                 {tab.label}
               </button>
           ))}
        </div>

        {/* Content Area */}
        <div className="flex-1 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 min-h-[500px]">
           <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                    {React.createElement(TABS.find(t => t.id === activeTab)?.icon || Box, { size: 20 })}
                  </div>
                  {activeTab === 'import' ? 'Importação e Manutenção' : `Gerenciar ${TABS.find(t => t.id === activeTab)?.label}`}
              </h3>
              {activeTab !== 'import' && (
                <span className="text-xs bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 px-3 py-1 rounded-full font-medium">
                    {currentItems.length} itens cadastrados
                </span>
              )}
           </div>

           {activeTab === 'import' ? (
               <div className="flex flex-col items-center h-full py-4 space-y-10">

                   {/* Upload Section */}
                   <div className="w-full max-w-md p-8 border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-2xl bg-slate-50 dark:bg-slate-800/50 flex flex-col items-center text-center">
                        <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mb-4">
                            <FileUp size={32} />
                        </div>
                        <h4 className="text-lg font-semibold text-slate-800 dark:text-white mb-2">Carregar Planilha CSV</h4>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">
                            O sistema detectará automaticamente para qual sessão os dados devem ir (Visitas, Tarefas, Pintura, etc.) baseando-se nos cabeçalhos.
                        </p>

                        <input 
                            type="file" 
                            accept=".csv" 
                            ref={fileInputRef}
                            onChange={handleFileUpload}
                            className="hidden" 
                            id="csv-upload"
                        />
                        <label 
                            htmlFor="csv-upload" 
                            className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg cursor-pointer transition-colors shadow-lg shadow-blue-200 dark:shadow-none font-medium"
                        >
                            Selecionar Arquivo
                        </label>
                   </div>

                   {importStatus && (
                       <div className={`w-full max-w-md p-4 rounded-xl flex items-start gap-3 ${importStatus.success ? 'bg-green-50 dark:bg-green-900/20 text-green-800 dark:text-green-200' : 'bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200'}`}>
                           {importStatus.success ? <CheckCircle className="shrink-0 mt-0.5" /> : <AlertCircle className="shrink-0 mt-0.5" />}
                           <div>
                               <p className="font-bold">{importStatus.message}</p>
                               <p className="text-sm opacity-90">{importStatus.details}</p>
                           </div>
                       </div>
                   )}

                   {/* Danger Zone */}
                   <div className="w-full max-w-2xl border-t border-slate-100 dark:border-slate-700 pt-8 mt-4">
                       <h5 className="text-sm font-bold text-red-600 dark:text-red-400 uppercase tracking-wide mb-4 flex items-center gap-2">
                           <AlertTriangle size={16} /> Zona de Perigo
                       </h5>
                       <div className="bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/30 p-4 rounded-xl flex items-center justify-between">
                           <div>
                               <p className="font-bold text-slate-800 dark:text-white">Limpar Banco de Dados</p>
                               <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                                   Remove todas as tarefas, visitas, compras e cronogramas. Não afeta as configurações (setores, torres, etc).
                               </p>
                           </div>
                           {!isConfirmingClear ? (
                               <button 
                                 onClick={() => setIsConfirmingClear(true)}
                                 className="px-4 py-2 bg-white dark:bg-slate-800 border border-red-200 dark:border-red-800 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg text-sm font-medium transition-colors"
                               >
                                   Limpar Dados
                               </button>
                           ) : (
                               <div className="flex items-center gap-2">
                                   <button 
                                     onClick={() => setIsConfirmingClear(false)}
                                     className="px-3 py-1.5 text-slate-500 hover:text-slate-700 text-xs font-medium"
                                   >
                                       Cancelar
                                   </button>
                                   <button 
                                     onClick={handleClearData}
                                     className="px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-bold transition-colors shadow-sm"
                                   >
                                       Confirmar Limpeza
                                   </button>
                               </div>
                           )}
                       </div>
                   </div>

                   {/* Help Text */}
                   <div className="w-full max-w-2xl">
                       <h5 className="text-sm font-bold text-slate-600 dark:text-slate-400 uppercase tracking-wide mb-3">Dicas de Colunas (CSV)</h5>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs text-slate-500 dark:text-slate-500">
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Visitas:</strong>
                               Torre, Unidade, Hora, Colaborador, Situação
                           </div>
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Tarefas:</strong>
                               Titulo, Local, Servico, Criticidade, Situacao
                           </div>
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Pintura:</strong>
                               Torre, Local, Tinta, Status, Previsao
                           </div>
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Compras:</strong>
                               Quantidade, Descricao, Local
                           </div>
                       </div>
                   </div>
               </div>
           ) : (
             <>
               {/* Add New Item Form */}
               <form onSubmit={handleAdd} className="flex gap-3 mb-8 bg-slate-50 dark:bg-slate-700/30 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                  <input 
                    type="text" 
                    value={newItemName}
                    onChange={(e) => setNewItemName(e.target.value)}
                    placeholder={`Adicionar novo em ${TABS.find(t => t.id === activeTab)?.label}...`}
                    className="flex-1 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  />
                  <button 
                    type="submit"
                    className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-medium transition-colors flex items-center gap-2 shadow-md shadow-blue-100 dark:shadow-none"
                  >
                    <Plus size={18} />
                    <span className="hidden sm:inline">Adicionar</span>
                  </button>
               </form>

               {/* List */}
               <div className="space-y-2">
                  {currentItems.length === 0 ? (
                     <div className="text-center py-12 flex flex-col items-center gap-3">
                        <div className="w-16 h-16 bg-slate-50 dark:bg-slate-700 rounded-full flex items-center justify-center text-slate-300 dark:text-slate-500">
                            <Box size={32} />
                        </div>
                        <p className="text-slate-400 dark:text-slate-500">Nenhum item cadastrado nesta categoria.</p>
                     </div>
                  ) : (
                    currentItems.map(item => (
                       <div key={item.id} className="flex items-center justify-between p-3 pl-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 group hover:border-blue-200 dark:hover:border-slate-500 hover:shadow-sm transition-all">
                          {editingId === item.id ? (
                            <div className="flex items-center gap-2 flex-1">
                                <input 
                                    type="text" 
                                    value={editingName} 
                                    onChange={(e) => setEditingName(e.target.value)}
                                    className="flex-1 px-3 py-1.5 bg-white dark:bg-slate-900 border border-blue-300 dark:border-blue-500 text-slate-800 dark:text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-200"
                                    autoFocus
                                />
                                <button onClick={() => saveEdit(item.id)} className="p-2 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg">
                                    <Check size={18} />
                                </button>
                                <button onClick={cancelEdit} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg">
                                    <X size={18} />
                                </button>
                            </div>
                          ) : (
                            <>
                                <div className="flex items-center gap-3">
                                    {activeTab === 'materials' && (
                                        <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-500 dark:text-slate-400">
                                            M
                                        </div>
                                    )}
                                    <span className="text-slate-700 dark:text-slate-300 font-medium">{item.name}</span>
                                </div>

                                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button 
                                        onClick={() => startEdit(item.id, item.name)}
                                        className="p-2 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                                        title="Editar"
                                    >
                                        <Edit2 size={16} />
                                    </button>
                                    <button 
                                        onClick={() => removeSettingItem(activeTab as keyof SettingsState, item.id)}
                                        className="p-2 text-slate-400 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                        title="Excluir"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </>
                          )}
                       </div>
                    ))
                  )}
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  build: {
    outDir: 'dist',
    sourcemap: false
  }
});

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { Task, SettingsState, CatalogItem, Visit, ScheduleItem, MonthlyScheduleItem, PaintingProject, PurchaseRequest } from '../types';
import { supabase } from '../lib/supabase';

interface DataContextType {
  tasks: Task[];
  visits: Visit[];
  schedule: ScheduleItem[];
  monthlySchedule: MonthlyScheduleItem[];
  paintingProjects: PaintingProject[];
  purchases: PurchaseRequest[];
  settings: SettingsState;
  isLoading: boolean;

  // Tasks
  addTask: (task: Omit<Task, 'id' | 'createdAt'>) => void;
  updateTask: (id: string, updates: Partial<Task>) => void;
  deleteTask: (id: string) => void;

  // Visits
  addVisit: (item: Omit<Visit, 'id'>) => void;
  updateVisit: (id: string, updates: Partial<Visit>) => void;
  deleteVisit: (id: string) => void;

  // Schedule (Weekly)
  addScheduleItem: (item: Omit<ScheduleItem, 'id'>) => void;
  updateScheduleItem: (id: string, updates: Partial<ScheduleItem>) => void;
  deleteScheduleItem: (id: string) => void;

  // Schedule (Monthly)
  addMonthlyScheduleItem: (item: Omit<MonthlyScheduleItem, 'id'>) => void;
  updateMonthlyScheduleItem: (id: string, updates: Partial<MonthlyScheduleItem>) => void;
  deleteMonthlyScheduleItem: (id: string) => void;

  // Painting
  addPaintingProject: (item: Omit<PaintingProject, 'id'>) => void;
  updatePaintingProject: (id: string, updates: Partial<PaintingProject>) => void;
  deletePaintingProject: (id: string) => void;

  // Purchases
  addPurchase: (item: Omit<PurchaseRequest, 'id'>) => void;
  updatePurchase: (id: string, updates: Partial<PurchaseRequest>) => void;
  deletePurchase: (id: string) => void;

  // Settings
  addSettingItem: (category: keyof SettingsState, name: string) => void;
  updateSettingItem: (category: keyof SettingsState, id: string, newName: string) => void;
  removeSettingItem: (category: keyof SettingsState, id: string) => void;

  exportTasksToCSV: () => void;
  importDataFromCSV: (csvContent: string) => Promise<{ success: boolean; message: string; type?: string; count?: number }>;

  // Danger Zone
  clearAllData: () => Promise<void>;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const initialSettings: SettingsState = {
  sectors: [],
  services: [],
  towers: [],
  responsibles: [],
  materials: [], 
  situations: []
};

export const DataProvider = ({ children }: { children?: ReactNode }) => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [visits, setVisits] = useState<Visit[]>([]);
  const [schedule, setSchedule] = useState<ScheduleItem[]>([]);
  const [monthlySchedule, setMonthlySchedule] = useState<MonthlyScheduleItem[]>([]);
  const [paintingProjects, setPaintingProjects] = useState<PaintingProject[]>([]);
  const [purchases, setPurchases] = useState<PurchaseRequest[]>([]);
  const [settings, setSettings] = useState<SettingsState>(initialSettings);
  const [isLoading, setIsLoading] = useState(true);

  // --- FETCH DATA FROM SUPABASE ---
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const [
          tasksRes, 
          visitsRes, 
          scheduleRes, 
          monthlyRes, 
          paintingRes, 
          purchasesRes,
          sectorsRes,
          servicesRes,
          towersRes,
          responsiblesRes,
          materialsRes,
          situationsRes
        ] = await Promise.all([
          supabase.from('tasks').select('*').order('created_at', { ascending: false }),
          supabase.from('visits').select('*'),
          supabase.from('schedule').select('*'),
          supabase.from('monthly_schedule').select('*'),
          supabase.from('painting_projects').select('*'),
          supabase.from('purchases').select('*'),
          supabase.from('sectors').select('*'),
          supabase.from('services').select('*'),
          supabase.from('towers').select('*'),
          supabase.from('responsibles').select('*'),
          supabase.from('materials').select('*'),
          supabase.from('situations').select('*')
        ]);

        if (tasksRes.data) {
            // Map keys from snake_case to camelCase manually for frontend compatibility
            const mappedTasks = tasksRes.data.map((t: any) => ({
                id: t.id,
                title: t.title,
                sectorId: t.sector_id,
                serviceId: t.service_id,
                towerId: t.tower_id,
                location: t.location,
                responsibleId: t.responsible_id,
                situation: t.situation,
                criticality: t.criticality,
                materials: t.materials || [],
                callDate: t.call_date,
                startDate: t.start_date,
                endDate: t.end_date,
                description: t.description,
                createdAt: t.created_at
            }));
            setTasks(mappedTasks);
        }
        if (visitsRes.data) setVisits(visitsRes.data.map((v:any) => ({...v, returnDate: v.return_date})));
        if (scheduleRes.data) setSchedule(scheduleRes.data);
        if (monthlyRes.data) setMonthlySchedule(monthlyRes.data);
        if (paintingRes.data) setPaintingProjects(paintingRes.data.map((p:any) => ({...p, endDateForecast: p.end_date_forecast, startDate: p.start_date, paintDetails: p.paint_details})));
        if (purchasesRes.data) setPurchases(purchasesRes.data.map((p:any) => ({...p, requestDate: p.request_date, approvalDate: p.approval_date, entryDate: p.entry_date})));

        setSettings({
            sectors: sectorsRes.data || [],
            services: servicesRes.data || [],
            towers: towersRes.data || [],
            responsibles: responsiblesRes.data || [],
            materials: materialsRes.data || [],
            situations: situationsRes.data || []
        });

      } catch (error) {
        console.error('Error fetching data from Supabase:', error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  // --- TASKS ---
  const addTask = async (newTask: Omit<Task, 'id' | 'createdAt'>) => {
    const tempId = `T-${Math.floor(1000 + Math.random() * 9000)}`;
    const now = new Date().toISOString();

    const dbTask = {
        id: tempId,
        title: newTask.title,
        sector_id: newTask.sectorId,
        service_id: newTask.serviceId,
        tower_id: newTask.towerId,
        location: newTask.location,
        responsible_id: newTask.responsibleId,
        situation: newTask.situation,
        criticality: newTask.criticality,
        materials: newTask.materials,
        call_date: newTask.callDate,
        start_date: newTask.startDate,
        end_date: newTask.endDate,
        description: newTask.description,
        created_at: now
    };

    // Optimistic Update
    const feTask = { ...newTask, id: tempId, createdAt: now };
    setTasks((prev) => [feTask, ...prev]);

    const { error } = await supabase.from('tasks').insert(dbTask);
    if (error) {
        console.error('Supabase Error:', error);
    }
  };

  const updateTask = async (id: string, updates: Partial<Task>) => {
    setTasks((prev) => prev.map((t) => (t.id === id ? { ...t, ...updates } : t)));

    // Map updates to snake_case
    const dbUpdates: any = {};
    if (updates.title) dbUpdates.title = updates.title;
    if (updates.sectorId) dbUpdates.sector_id = updates.sectorId;
    if (updates.serviceId) dbUpdates.service_id = updates.serviceId;
    if (updates.towerId) dbUpdates.tower_id = updates.towerId;
    if (updates.location) dbUpdates.location = updates.location;
    if (updates.responsibleId) dbUpdates.responsible_id = updates.responsibleId;
    if (updates.situation) dbUpdates.situation = updates.situation;
    if (updates.criticality) dbUpdates.criticality = updates.criticality;
    if (updates.materials) dbUpdates.materials = updates.materials;
    if (updates.callDate) dbUpdates.call_date = updates.callDate;
    if (updates.startDate) dbUpdates.start_date = updates.startDate;
    if (updates.endDate) dbUpdates.end_date = updates.endDate;

    await supabase.from('tasks').update(dbUpdates).eq('id', id);
  };

  const deleteTask = async (id: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
    await supabase.from('tasks').delete().eq('id', id);
  };

  // --- VISITS ---
  const addVisit = async (item: Omit<Visit, 'id'>) => {
     const newId = Math.random().toString(36).substr(2, 9);
     const newItem = { ...item, id: newId };
     setVisits(prev => [newItem, ...prev]);

     await supabase.from('visits').insert({
         id: newId,
         tower: item.tower,
         unit: item.unit,
         situation: item.situation,
         time: item.time,
         collaborator: item.collaborator,
         status: item.status,
         return_date: item.returnDate
     });
  };
  const updateVisit = async (id: string, updates: Partial<Visit>) => {
     setVisits(prev => prev.map(v => v.id === id ? { ...v, ...updates } : v));
     const dbUpdates: any = {...updates};
     if (updates.returnDate) {
         dbUpdates.return_date = updates.returnDate;
         delete dbUpdates.returnDate;
     }
     await supabase.from('visits').update(dbUpdates).eq('id', id);
  };
  const deleteVisit = async (id: string) => {
     setVisits(prev => prev.filter(v => v.id !== id));
     await supabase.from('visits').delete().eq('id', id);
  };

  // --- SCHEDULE (WEEKLY) ---
  const addScheduleItem = async (item: Omit<ScheduleItem, 'id'>) => {
      const newId = Math.random().toString(36).substr(2, 9);
      const newItem = { ...item, id: newId };
      setSchedule(prev => [newItem, ...prev]);
      await supabase.from('schedule').insert(newItem);
  };
  const updateScheduleItem = async (id: string, updates: Partial<ScheduleItem>) => {
      setSchedule(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
      await supabase.from('schedule').update(updates).eq('id', id);
  };
  const deleteScheduleItem = async (id: string) => {
      setSchedule(prev => prev.filter(s => s.id !== id));
      await supabase.from('schedule').delete().eq('id', id);
  };

  // --- SCHEDULE (MONTHLY) ---
  const addMonthlyScheduleItem = async (item: Omit<MonthlyScheduleItem, 'id'>) => {
      const newId = Math.random().toString(36).substr(2, 9);
      const newItem = { ...item, id: newId };
      setMonthlySchedule(prev => [newItem, ...prev]);
      await supabase.from('monthly_schedule').insert(newItem);
  };
  const updateMonthlyScheduleItem = async (id: string, updates: Partial<MonthlyScheduleItem>) => {
      setMonthlySchedule(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
      await supabase.from('monthly_schedule').update(updates).eq('id', id);
  };
  const deleteMonthlyScheduleItem = async (id: string) => {
      setMonthlySchedule(prev => prev.filter(s => s.id !== id));
      await supabase.from('monthly_schedule').delete().eq('id', id);
  };

  // --- PAINTING ---
  const addPaintingProject = async (item: Omit<PaintingProject, 'id'>) => {
      const newId = Math.random().toString(36).substr(2, 9);
      const newItem = { ...item, id: newId };
      setPaintingProjects(prev => [newItem, ...prev]);

      await supabase.from('painting_projects').insert({
          id: newId,
          tower: item.tower,
          local: item.local,
          criticality: item.criticality,
          start_date: item.startDate,
          end_date_forecast: item.endDateForecast,
          status: item.status,
          paint_details: item.paintDetails,
          quantity: item.quantity
      });
  };
  const updatePaintingProject = async (id: string, updates: Partial<PaintingProject>) => {
      setPaintingProjects(prev => prev.map(p => p.id === id ? { ...p, ...updates } : p));

      const dbUpdates: any = {};
      if(updates.tower) dbUpdates.tower = updates.tower;
      if(updates.local) dbUpdates.local = updates.local;
      if(updates.criticality) dbUpdates.criticality = updates.criticality;
      if(updates.startDate) dbUpdates.start_date = updates.startDate;
      if(updates.endDateForecast) dbUpdates.end_date_forecast = updates.endDateForecast;
      if(updates.status) dbUpdates.status = updates.status;
      if(updates.paintDetails) dbUpdates.paint_details = updates.paintDetails;
      if(updates.quantity) dbUpdates.quantity = updates.quantity;

      await supabase.from('painting_projects').update(dbUpdates).eq('id', id);
  };
  const deletePaintingProject = async (id: string) => {
      setPaintingProjects(prev => prev.filter(p => p.id !== id));
      await supabase.from('painting_projects').delete().eq('id', id);
  };

  // --- PURCHASES ---
  const addPurchase = async (item: Omit<PurchaseRequest, 'id'>) => {
      const newId = Math.random().toString(36).substr(2, 9);
      const newItem = { ...item, id: newId };
      setPurchases(prev => [newItem, ...prev]);

      await supabase.from('purchases').insert({
          id: newId,
          quantity: item.quantity,
          description: item.description,
          local: item.local,
          request_date: item.requestDate,
          approval_date: item.approvalDate,
          entry_date: item.entryDate
      });
  };
  const updatePurchase = async (id: string, updates: Partial<PurchaseRequest>) => {
      setPurchases(prev => prev.map(p => p.id === id ? { ...p, ...updates } : p));

      const dbUpdates: any = {};
      if(updates.quantity) dbUpdates.quantity = updates.quantity;
      if(updates.description) dbUpdates.description = updates.description;
      if(updates.local) dbUpdates.local = updates.local;
      if(updates.requestDate) dbUpdates.request_date = updates.requestDate;
      if(updates.approvalDate) dbUpdates.approval_date = updates.approvalDate;
      if(updates.entryDate) dbUpdates.entry_date = updates.entryDate;

      await supabase.from('purchases').update(dbUpdates).eq('id', id);
  };
  const deletePurchase = async (id: string) => {
      setPurchases(prev => prev.filter(p => p.id !== id));
      await supabase.from('purchases').delete().eq('id', id);
  };

  // --- SETTINGS ---
  const addSettingItem = async (category: keyof SettingsState, name: string) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newItem: CatalogItem = { id: newId, name };

    setSettings((prev) => ({
      ...prev,
      [category]: [...prev[category], newItem],
    }));

    await supabase.from(category).insert(newItem);
  };

  const updateSettingItem = async (category: keyof SettingsState, id: string, newName: string) => {
    setSettings((prev) => ({
      ...prev,
      [category]: prev[category].map(item => 
        item.id === id ? { ...item, name: newName } : item
      ),
    }));

    await supabase.from(category).update({ name: newName }).eq('id', id);
  };

  const removeSettingItem = async (category: keyof SettingsState, id: string) => {
    setSettings((prev) => ({
      ...prev,
      [category]: prev[category].filter((item) => item.id !== id),
    }));
    await supabase.from(category).delete().eq('id', id);
  };

  const exportTasksToCSV = () => {
    const headers = ['ID', 'Serviço', 'Torre', 'Local', 'Situação', 'Criticidade', 'Data Chamado', 'Materiais'];
    const findName = (list: CatalogItem[], id: string) => list.find(i => i.id === id)?.name || id;

    const rows = tasks.map(t => {
        const service = findName(settings.services, t.serviceId);
        const tower = findName(settings.towers, t.towerId);
        const materials = t.materials.map(mId => findName(settings.materials, mId)).join('; ');

        return [t.id, service, tower, t.location, t.situation, t.criticality, t.callDate, materials];
    });

    let csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(",") + "\n" 
        + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "tarefas_villaprivilege.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- DANGER ZONE: CLEAR ALL DATA ---
  const clearAllData = async () => {
      setTasks([]);
      setVisits([]);
      setSchedule([]);
      setMonthlySchedule([]);
      setPaintingProjects([]);
      setPurchases([]);

      await Promise.all([
          supabase.from('tasks').delete().neq('id', '0'),
          supabase.from('visits').delete().neq('id', '0'),
          supabase.from('schedule').delete().neq('id', '0'),
          supabase.from('monthly_schedule').delete().neq('id', '0'),
          supabase.from('painting_projects').delete().neq('id', '0'),
          supabase.from('purchases').delete().neq('id', '0')
      ]);
  };

  // Helper to normalize CSV dates (DD/MM/YYYY) to ISO (YYYY-MM-DD)
  const normalizeDate = (dateStr: string) => {
      if (!dateStr || dateStr.trim() === '') return new Date().toISOString().split('T')[0];
      // Check for DD/MM/YYYY
      if (dateStr.includes('/')) {
          const parts = dateStr.split('/');
          if (parts.length === 3) {
              const d = parts[0].padStart(2, '0');
              const m = parts[1].padStart(2, '0');
              const y = parts[2];
              return `${y}-${m}-${d}`;
          }
      }
      return dateStr;
  };

  // --- SMART IMPORT LOGIC (ASYNC) ---
  const importDataFromCSV = async (csvContent: string): Promise<{ success: boolean; message: string; type?: string; count?: number }> => {
    try {
        const lines = csvContent.split(/\r\n|\n/);
        if (lines.length < 2) return { success: false, message: 'Arquivo vazio ou formato inválido.' };

        // 1. Detect Delimiter (Comma or Semicolon)
        const headerLine = lines[0];
        const delimiter = headerLine.includes(';') ? ';' : ',';
        const headers = headerLine.split(delimiter).map(h => h.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, ""));

        const getValue = (row: string[], headerName: string): string => {
            const index = headers.findIndex(h => h.includes(headerName));
            if (index === -1) return '';
            return row[index]?.trim().replace(/^"|"$/g, '') || '';
        };

        const rows = lines.slice(1).map(line => {
            if (!line.trim()) return null;
            if (delimiter === ',') {
                 return line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/);
            }
            return line.split(';');
        }).filter(r => r && r.length > 1) as string[][];

        // 2. Identify Section
        let detectedType = '';
        if (headers.some(h => h.includes('unidade') && h.includes('torre'))) detectedType = 'visits';
        else if (headers.some(h => h.includes('tinta') || h.includes('pintura') || h.includes('demao'))) detectedType = 'painting';
        else if (headers.some(h => h.includes('quantidade') && (h.includes('descricao') || h.includes('descrição')))) detectedType = 'purchases';
        else if (headers.some(h => h.includes('segunda') && h.includes('terca'))) detectedType = 'weekly_schedule';
        else if (headers.some(h => h.includes('semana 1'))) detectedType = 'monthly_schedule';
        else if (headers.some(h => h.includes('titulo') || h.includes('servico') || h.includes('criticidade'))) detectedType = 'tasks';

        // 3. Process Data
        let count = 0;

        // Helper for Settings (We add to DB immediately)
        const tempSettings = { ...settings };
        let hasSettingsUpdates = false;

        // Note: For simplicity in bulk import, we assume unique names logic holds. 
        // Real-world would need to await check, but here we optimistically use local cache + fire-and-forget insert for settings
        const findOrAdd = (category: keyof SettingsState, rawValue: string): string => {
            if (!rawValue) return tempSettings[category][0]?.id;
            const cleanVal = rawValue.trim();
            const matchId = tempSettings[category].find(i => i.id === cleanVal);
            if (matchId) return matchId.id;
            const matchName = tempSettings[category].find(i => i.name.toLowerCase() === cleanVal.toLowerCase());
            if (matchName) return matchName.id;

            const newId = Math.random().toString(36).substr(2, 9);
            const newItem = { id: newId, name: cleanVal };
            tempSettings[category] = [...tempSettings[category], newItem];
            hasSettingsUpdates = true;
            // Fire async insert
            supabase.from(category).insert(newItem).then();
            return newId;
        };

        if (detectedType === 'visits') {
            const newVisits = rows.map(r => ({
                id: Math.random().toString(36).substr(2, 9),
                tower: getValue(r, 'torre') || 'T1',
                unit: getValue(r, 'unidade') || '000',
                situation: getValue(r, 'situacao') || getValue(r, 'motivo') || 'Importado',
                time: getValue(r, 'hora') || '08:00',
                collaborator: getValue(r, 'colaborador') || getValue(r, 'responsavel') || '-',
                status: getValue(r, 'status') || 'Pendente',
                return_date: getValue(r, 'retorno') || '-'
            }));

            // Wait for Supabase
            const { error } = await supabase.from('visits').insert(newVisits);
            if (error) throw error;

            setVisits(prev => [...newVisits.map(v => ({...v, returnDate: v.return_date})), ...prev]);
            count = newVisits.length;

        } else if (detectedType === 'painting') {
            const newProjects = rows.map(r => ({
                id: Math.random().toString(36).substr(2, 9),
                tower: getValue(r, 'torre') || 'Geral',
                local: getValue(r, 'local') || 'Importado',
                criticality: (getValue(r, 'criticidade') as any) || 'Média',
                start_date: normalizeDate(getValue(r, 'inicio')),
                end_date_forecast: normalizeDate(getValue(r, 'previsao')),
                status: getValue(r, 'status') || '',
                paint_details: getValue(r, 'tinta') || getValue(r, 'detalhe') || '',
                quantity: getValue(r, 'quantidade') || ''
            }));

            const { error } = await supabase.from('painting_projects').insert(newProjects);
            if (error) throw error;

            setPaintingProjects(prev => [...newProjects.map(p => ({...p, startDate: p.start_date, endDateForecast: p.end_date_forecast, paintDetails: p.paint_details})), ...prev]);
            count = newProjects.length;

        } else if (detectedType === 'purchases') {
             const newPurchases = rows.map(r => ({
                id: Math.random().toString(36).substr(2, 9),
                quantity: Number(getValue(r, 'quantidade')) || 1,
                description: getValue(r, 'descricao') || 'Item Importado',
                local: getValue(r, 'local') || 'Almoxarifado',
                request_date: normalizeDate(getValue(r, 'solicitacao')),
                approval_date: normalizeDate(getValue(r, 'aprovacao')),
                entry_date: normalizeDate(getValue(r, 'entrada'))
             }));

             const { error } = await supabase.from('purchases').insert(newPurchases);
             if (error) throw error;

             setPurchases(prev => [...newPurchases.map(p => ({...p, requestDate: p.request_date, approvalDate: p.approval_date, entryDate: p.entry_date})), ...prev]);
             count = newPurchases.length;

        } else if (detectedType === 'weekly_schedule') {
             const newSchedule = rows.map(r => ({
                 id: Math.random().toString(36).substr(2, 9),
                 shift: getValue(r, 'turno') || 'MANHÃ',
                 monday: getValue(r, 'segunda') || '-',
                 tuesday: getValue(r, 'terca') || '-',
                 wednesday: getValue(r, 'quarta') || '-',
                 thursday: getValue(r, 'quinta') || '-',
                 friday: getValue(r, 'sexta') || '-',
                 saturday: getValue(r, 'sabado') || '-'
             }));

             const { error } = await supabase.from('schedule').insert(newSchedule);
             if (error) throw error;

             setSchedule(prev => [...newSchedule, ...prev]);
             count = newSchedule.length;

        } else if (detectedType === 'monthly_schedule') {
             const newMonthly = rows.map(r => ({
                 id: Math.random().toString(36).substr(2, 9),
                 shift: getValue(r, 'turno') || 'AREA',
                 week1: getValue(r, 'semana 1') || '-',
                 week2: getValue(r, 'semana 2') || '-',
                 week3: getValue(r, 'semana 3') || '-',
                 week4: getValue(r, 'semana 4') || '-'
             }));

             const { error } = await supabase.from('monthly_schedule').insert(newMonthly);
             if (error) throw error;

             setMonthlySchedule(prev => [...newMonthly, ...prev]);
             count = newMonthly.length;

        } else {
             const newTasks = rows.map(r => {
                 const rawService = getValue(r, 'servico') || getValue(r, 'tipo');
                 const rawTower = getValue(r, 'torre');
                 const rawSector = getValue(r, 'setor');
                 const rawResp = getValue(r, 'responsavel') || getValue(r, 'colaborador');
                 const rawSit = getValue(r, 'situacao') || getValue(r, 'status');

                 const serviceId = findOrAdd('services', rawService || 'Serviço Geral');
                 const towerId = findOrAdd('towers', rawTower || 'Geral');
                 const sectorId = findOrAdd('sectors', rawSector || 'Geral');
                 const responsibleId = findOrAdd('responsibles', rawResp || 'Não Identificado');

                 let situationName = rawSit ? rawSit.trim() : 'Aberto';
                 situationName = situationName.charAt(0).toUpperCase() + situationName.slice(1);

                 const sitExists = tempSettings.situations.find(s => s.name.toLowerCase() === situationName.toLowerCase());
                 if (!sitExists) {
                     const newItem = { id: Math.random().toString(36).substr(2, 9), name: situationName };
                     tempSettings.situations = [...tempSettings.situations, newItem];
                     hasSettingsUpdates = true;
                     supabase.from('situations').insert(newItem).then();
                 } else {
                     situationName = sitExists.name;
                 }

                 return {
                    id: `T-${Math.floor(Math.random() * 100000)}`,
                    title: getValue(r, 'titulo') || getValue(r, 'descricao') || 'Tarefa Importada',
                    sector_id: sectorId, 
                    service_id: serviceId,
                    tower_id: towerId,
                    location: getValue(r, 'local') || 'Geral',
                    responsible_id: responsibleId,
                    situation: situationName,
                    criticality: (getValue(r, 'criticidade') as any) || 'Média',
                    materials: [],
                    call_date: normalizeDate(getValue(r, 'data')),
                    created_at: new Date().toISOString()
                 };
             });

             if (hasSettingsUpdates) {
                 setSettings(tempSettings);
             }

             const { error } = await supabase.from('tasks').insert(newTasks);
             if (error) throw error;

             // Convert snake_case back to camelCase for local state
             const feTasks = newTasks.map(t => ({
                 id: t.id,
                 title: t.title,
                 sectorId: t.sector_id,
                 serviceId: t.service_id,
                 towerId: t.tower_id,
                 location: t.location,
                 responsibleId: t.responsible_id,
                 situation: t.situation,
                 criticality: t.criticality,
                 materials: t.materials,
                 callDate: t.call_date,
                 createdAt: t.created_at
             }));

             setTasks(prev => [...feTasks, ...prev]);
             count = newTasks.length;
             detectedType = 'tasks';
        }

        return { success: true, message: 'Importação realizada e salva no servidor!', type: detectedType, count };

    } catch (error: any) {
        console.error("Import Error", error);
        return { success: false, message: 'Erro ao salvar no banco de dados: ' + error.message };
    }
  };

  return (
    <DataContext.Provider value={{ 
        tasks, visits, schedule, monthlySchedule, paintingProjects, purchases, settings, isLoading,
        addTask, updateTask, deleteTask, 
        addVisit, updateVisit, deleteVisit,
        addScheduleItem, updateScheduleItem, deleteScheduleItem,
        addMonthlyScheduleItem, updateMonthlyScheduleItem, deleteMonthlyScheduleItem,
        addPaintingProject, updatePaintingProject, deletePaintingProject,
        addPurchase, updatePurchase, deletePurchase,
        addSettingItem, updateSettingItem, removeSettingItem, 
        exportTasksToCSV, importDataFromCSV,
        clearAllData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useData must be used within a DataProvider');
  return context;
};

import React, { useState, useRef } from 'react';
import { useData } from '../../context/DataContext';
import { SettingsState } from '../../types';
import { Plus, Trash2, Tag, User as UserIcon, Wrench, Briefcase, Box, Edit2, Check, X, Activity, Upload, FileUp, AlertCircle, CheckCircle, AlertTriangle, Eraser } from 'lucide-react';

const TABS = [
  { id: 'towers', label: 'Torres', icon: Box },
  { id: 'sectors', label: 'Setores', icon: Briefcase },
  { id: 'services', label: 'Tipos de Serviço', icon: Wrench },
  { id: 'responsibles', label: 'Responsáveis', icon: UserIcon },
  { id: 'situations', label: 'Situação da Tarefa', icon: Activity },
  { id: 'materials', label: 'Materiais Disponíveis', icon: Tag },
  { id: 'import', label: 'Importação (CSV)', icon: Upload }, 
];

export const Settings = () => {
  const { settings, addSettingItem, updateSettingItem, removeSettingItem, importDataFromCSV, clearAllData } = useData();
  const [activeTab, setActiveTab] = useState<keyof SettingsState | 'import'>('towers');
  const [newItemName, setNewItemName] = useState('');

  // Import State
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [importStatus, setImportStatus] = useState<{success?: boolean; message?: string; details?: string} | null>(null);
  const [isConfirmingClear, setIsConfirmingClear] = useState(false);
  const [isImporting, setIsImporting] = useState(false);

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newItemName.trim() && activeTab !== 'import') {
      addSettingItem(activeTab as keyof SettingsState, newItemName);
      setNewItemName('');
    }
  };

  const startEdit = (id: string, currentName: string) => {
    setEditingId(id);
    setEditingName(currentName);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditingName('');
  };

  const saveEdit = (id: string) => {
    if (editingName.trim()) {
      updateSettingItem(activeTab as keyof SettingsState, id, editingName);
      setEditingId(null);
      setEditingName('');
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setIsImporting(true);
      setImportStatus(null);

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);

          if (result.success) {
              setImportStatus({
                  success: true,
                  message: 'Importação Concluída!',
                  details: `Foram importados ${result.count} itens para a seção: ${translateType(result.type)}`
              });
          } else {
              setImportStatus({
                  success: false,
                  message: 'Falha na Importação',
                  details: result.message
              });
          }
          if (fileInputRef.current) fileInputRef.current.value = '';
          setIsImporting(false);
      };
      reader.readAsText(file);
  };

  const handleClearData = async () => {
      await clearAllData();
      setIsConfirmingClear(false);
      setImportStatus({
          success: true,
          message: 'Banco de Dados Limpo',
          details: 'Todos os registros de tarefas, visitas, compras e cronogramas foram removidos.'
      });
  };

  const translateType = (type?: string) => {
      switch(type) {
          case 'visits': return 'Visitas Técnicas';
          case 'tasks': return 'Tarefas de Manutenção';
          case 'painting': return 'Projetos de Pintura';
          case 'purchases': return 'Compras / Almoxarifado';
          case 'weekly_schedule': return 'Cronograma Semanal';
          case 'monthly_schedule': return 'Cronograma Mensal';
          default: return 'Geral';
      }
  };

  const currentItems = activeTab !== 'import' ? settings[activeTab as keyof SettingsState] : [];

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Configurações do Sistema</h2>
        <p className="text-slate-500 dark:text-slate-400">Gerencie todos os cadastros auxiliares do Villa Privilege</p>
      </div>

      <div className="flex flex-col lg:flex-row gap-8">
        <div className="w-full lg:w-64 flex flex-col gap-2">
           {TABS.map(tab => (
               <button
                 key={tab.id}
                 onClick={() => {
                   setActiveTab(tab.id as any);
                   setEditingId(null);
                   setImportStatus(null);
                   setIsConfirmingClear(false);
                 }}
                 className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    activeTab === tab.id 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-200 dark:shadow-none' 
                    : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700 border border-transparent hover:border-slate-200 dark:hover:border-slate-700'
                 }`}
               >
                 <tab.icon size={18} />
                 {tab.label}
               </button>
           ))}
        </div>

        <div className="flex-1 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 min-h-[500px]">
           <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                  <div className="p-2 bg-blue-100 dark:bg-blue-900/30 rounded-lg text-blue-600 dark:text-blue-400">
                    {React.createElement(TABS.find(t => t.id === activeTab)?.icon || Box, { size: 20 })}
                  </div>
                  {activeTab === 'import' ? 'Importação e Manutenção' : `Gerenciar ${TABS.find(t => t.id === activeTab)?.label}`}
              </h3>
              {activeTab !== 'import' && (
                <span className="text-xs bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 px-3 py-1 rounded-full font-medium">
                    {currentItems.length} itens cadastrados
                </span>
              )}
           </div>

           {activeTab === 'import' ? (
               <div className="flex flex-col items-center h-full py-4 space-y-10">

                   <div className="w-full max-w-md p-8 border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-2xl bg-slate-50 dark:bg-slate-800/50 flex flex-col items-center text-center">
                        <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mb-4">
                            <FileUp size={32} />
                        </div>
                        <h4 className="text-lg font-semibold text-slate-800 dark:text-white mb-2">Carregar Planilha CSV</h4>
                        <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">
                            O sistema detectará automaticamente para qual sessão os dados devem ir (Visitas, Tarefas, Pintura, etc.) baseando-se nos cabeçalhos.
                        </p>

                        <input 
                            type="file" 
                            accept=".csv" 
                            ref={fileInputRef}
                            onChange={handleFileUpload}
                            className="hidden" 
                            id="csv-upload"
                            disabled={isImporting}
                        />
                        <label 
                            htmlFor="csv-upload" 
                            className={`px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg cursor-pointer transition-colors shadow-lg shadow-blue-200 dark:shadow-none font-medium ${isImporting ? 'opacity-50 cursor-wait' : ''}`}
                        >
                            {isImporting ? 'Importando...' : 'Selecionar Arquivo'}
                        </label>
                   </div>

                   {importStatus && (
                       <div className={`w-full max-w-md p-4 rounded-xl flex items-start gap-3 ${importStatus.success ? 'bg-green-50 dark:bg-green-900/20 text-green-800 dark:text-green-200' : 'bg-red-50 dark:bg-red-900/20 text-red-800 dark:text-red-200'}`}>
                           {importStatus.success ? <CheckCircle className="shrink-0 mt-0.5" /> : <AlertCircle className="shrink-0 mt-0.5" />}
                           <div>
                               <p className="font-bold">{importStatus.message}</p>
                               <p className="text-sm opacity-90">{importStatus.details}</p>
                           </div>
                       </div>
                   )}

                   <div className="w-full max-w-2xl border-t border-slate-100 dark:border-slate-700 pt-8 mt-4">
                       <h5 className="text-sm font-bold text-red-600 dark:text-red-400 uppercase tracking-wide mb-4 flex items-center gap-2">
                           <AlertTriangle size={16} /> Zona de Perigo
                       </h5>
                       <div className="bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/30 p-4 rounded-xl flex items-center justify-between">
                           <div>
                               <p className="font-bold text-slate-800 dark:text-white">Limpar Banco de Dados</p>
                               <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                                   Remove todas as tarefas, visitas, compras e cronogramas. Não afeta as configurações (setores, torres, etc).
                               </p>
                           </div>
                           {!isConfirmingClear ? (
                               <button 
                                 onClick={() => setIsConfirmingClear(true)}
                                 className="px-4 py-2 bg-white dark:bg-slate-800 border border-red-200 dark:border-red-800 text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg text-sm font-medium transition-colors"
                               >
                                   Limpar Dados
                               </button>
                           ) : (
                               <div className="flex items-center gap-2">
                                   <button 
                                     onClick={() => setIsConfirmingClear(false)}
                                     className="px-3 py-1.5 text-slate-500 hover:text-slate-700 text-xs font-medium"
                                   >
                                       Cancelar
                                   </button>
                                   <button 
                                     onClick={handleClearData}
                                     className="px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-bold transition-colors shadow-sm"
                                   >
                                       Confirmar Limpeza
                                   </button>
                               </div>
                           )}
                       </div>
                   </div>

                   <div className="w-full max-w-2xl">
                       <h5 className="text-sm font-bold text-slate-600 dark:text-slate-400 uppercase tracking-wide mb-3">Dicas de Colunas (CSV)</h5>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs text-slate-500 dark:text-slate-500">
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Visitas:</strong>
                               Torre, Unidade, Hora, Colaborador, Situação
                           </div>
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Tarefas:</strong>
                               Titulo, Local, Servico, Criticidade, Situacao
                           </div>
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Pintura:</strong>
                               Torre, Local, Tinta, Status, Previsao
                           </div>
                           <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded border border-slate-200 dark:border-slate-700">
                               <strong className="block text-slate-700 dark:text-slate-300 mb-1">Para Compras:</strong>
                               Quantidade, Descricao, Local
                           </div>
                       </div>
                   </div>
               </div>
           ) : (
             <>
               <form onSubmit={handleAdd} className="flex gap-3 mb-8 bg-slate-50 dark:bg-slate-700/30 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                  <input 
                    type="text" 
                    value={newItemName}
                    onChange={(e) => setNewItemName(e.target.value)}
                    placeholder={`Adicionar novo em ${TABS.find(t => t.id === activeTab)?.label}...`}
                    className="flex-1 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 text-slate-800 dark:text-white rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  />
                  <button 
                    type="submit"
                    className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-medium transition-colors flex items-center gap-2 shadow-md shadow-blue-100 dark:shadow-none"
                  >
                    <Plus size={18} />
                    <span className="hidden sm:inline">Adicionar</span>
                  </button>
               </form>

               <div className="space-y-2">
                  {currentItems.length === 0 ? (
                     <div className="text-center py-12 flex flex-col items-center gap-3">
                        <div className="w-16 h-16 bg-slate-50 dark:bg-slate-700 rounded-full flex items-center justify-center text-slate-300 dark:text-slate-500">
                            <Box size={32} />
                        </div>
                        <p className="text-slate-400 dark:text-slate-500">Nenhum item cadastrado nesta categoria.</p>
                     </div>
                  ) : (
                    currentItems.map(item => (
                       <div key={item.id} className="flex items-center justify-between p-3 pl-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 group hover:border-blue-200 dark:hover:border-slate-500 hover:shadow-sm transition-all">
                          {editingId === item.id ? (
                            <div className="flex items-center gap-2 flex-1">
                                <input 
                                    type="text" 
                                    value={editingName} 
                                    onChange={(e) => setEditingName(e.target.value)}
                                    className="flex-1 px-3 py-1.5 bg-white dark:bg-slate-900 border border-blue-300 dark:border-blue-500 text-slate-800 dark:text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-200"
                                    autoFocus
                                />
                                <button onClick={() => saveEdit(item.id)} className="p-2 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg">
                                    <Check size={18} />
                                </button>
                                <button onClick={cancelEdit} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg">
                                    <X size={18} />
                                </button>
                            </div>
                          ) : (
                            <>
                                <div className="flex items-center gap-3">
                                    {activeTab === 'materials' && (
                                        <div className="w-8 h-8 rounded-full bg-slate-100 dark:bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-500 dark:text-slate-400">
                                            M
                                        </div>
                                    )}
                                    <span className="text-slate-700 dark:text-slate-300 font-medium">{item.name}</span>
                                </div>

                                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button 
                                        onClick={() => startEdit(item.id, item.name)}
                                        className="p-2 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                                        title="Editar"
                                    >
                                        <Edit2 size={16} />
                                    </button>
                                    <button 
                                        onClick={() => removeSettingItem(activeTab as keyof SettingsState, item.id)}
                                        className="p-2 text-slate-400 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                        title="Excluir"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </>
                          )}
                       </div>
                    ))
                  )}
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { useAuth } from '../../context/AuthContext';
import { Plus, Search, Filter, Download, Edit2, Trash2, Wrench, Upload, Eraser, Calendar } from 'lucide-react';
import { TaskFormModal } from '../ui/TaskFormModal';
import { Task } from '../../types';

export const TaskList = () => {
  const { tasks, settings, deleteTask, exportTasksToCSV, importDataFromCSV } = useData();
  const { user } = useAuth();
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter States
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSituation, setFilterSituation] = useState('Todos');
  const [dateFilter, setDateFilter] = useState<'all' | 'week' | 'month'>('all');

  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  const getResponsibleName = (id: string) => settings.responsibles.find(r => r.id === id)?.name || 'N/A';
  const getSectorName = (id: string) => settings.sectors.find(s => s.id === id)?.name || 'N/A';
  const getServiceName = (id: string) => settings.services.find(s => s.id === id)?.name || 'Serviço';
  const getTowerName = (id: string) => settings.towers.find(t => t.id === id)?.name || 'Torre';

  const getMaterialNames = (ids: string[]) => {
      if (!ids || ids.length === 0) return null;
      return ids.map(id => settings.materials.find(m => m.id === id)?.name).filter(Boolean).join(', ');
  };

  const handleEdit = (task: Task) => {
    setEditingTask(task);
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setEditingTask(undefined);
    setIsModalOpen(true);
  };

  const handleClearFilters = () => {
      setSearchTerm('');
      setFilterSituation('Todos');
      setDateFilter('all');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = async (event) => {
          const content = event.target?.result as string;
          const result = await importDataFromCSV(content);
          alert(`${result.message}\n${result.count ? `Importados: ${result.count} registros.` : ''}`);
          e.target.value = ''; 
      };
      reader.readAsText(file);
  };

  const filteredTasks = tasks.filter(task => {
    // 1. Search Filter
    const serviceName = getServiceName(task.serviceId).toLowerCase();
    const towerName = getTowerName(task.towerId).toLowerCase();
    const matchesSearch = task.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          task.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          serviceName.includes(searchTerm.toLowerCase()) ||
                          towerName.includes(searchTerm.toLowerCase());

    // 2. Situation Filter
    const matchesSituation = filterSituation === 'Todos' || task.situation === filterSituation;

    // 3. Date Filter (Based on Call Date)
    let matchesDate = true;
    if (dateFilter !== 'all') {
        const taskDate = new Date(task.callDate);
        const now = new Date();

        if (dateFilter === 'month') {
            matchesDate = taskDate.getMonth() === now.getMonth() && taskDate.getFullYear() === now.getFullYear();
        } else if (dateFilter === 'week') {
            const startOfWeek = new Date(now);
            startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday
            startOfWeek.setHours(0, 0, 0, 0);

            const endOfWeek = new Date(startOfWeek);
            endOfWeek.setDate(startOfWeek.getDate() + 6); // Saturday
            endOfWeek.setHours(23, 59, 59, 999);

            matchesDate = taskDate >= startOfWeek && taskDate <= endOfWeek;
        }
    }

    return matchesSearch && matchesSituation && matchesDate;
  });

  const getStatusColor = (status: string) => {
    switch(status) {
      case 'Concluído': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300';
      case 'Em Andamento': return 'bg-sky-100 text-sky-700 dark:bg-sky-900/30 dark:text-sky-300';
      case 'Cancelado': return 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300';
      default: return 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300'; // Aberto
    }
  };

  const getCriticalityColor = (crit: string) => {
    switch(crit) {
        case 'Alta': return 'text-red-600 bg-red-50 border-red-100 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/30';
        case 'Média': return 'text-amber-600 bg-amber-50 border-amber-100 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-900/30';
        default: return 'text-slate-600 bg-slate-50 border-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:border-slate-700';
    }
  };

  // Short Date Formatter (DD/MM)
  const formatShortDate = (dateString?: string) => {
      if (!dateString || dateString.trim() === '') return '-';

      try {
        // Handle ISO or manual input
        const date = new Date(dateString);
        if (isNaN(date.getTime())) {
             // Try split if DD/MM/YYYY
             if(dateString.includes('/')) {
                 const parts = dateString.split('/');
                 if(parts.length >= 2) return `${parts[0]}/${parts[1]}`;
             }
             return '-';
        }
        return date.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
      } catch (e) {
          return '-';
      }
  };

  const hasActiveFilters = searchTerm !== '' || filterSituation !== 'Todos' || dateFilter !== 'all';

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">Tarefas de Manutenção</h2>
          <p className="text-slate-500 dark:text-slate-400">Gerencie todas as ordens de serviço</p>
        </div>
        <div className="flex gap-2">
           <label className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors cursor-pointer">
              <Upload size={18} />
              <span className="hidden sm:inline">Importar</span>
              <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
           </label>
           <button onClick={exportTasksToCSV} className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
              <Download size={18} />
              <span className="hidden sm:inline">Exportar</span>
           </button>
           <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 shadow-sm shadow-blue-200 dark:shadow-none transition-all transform active:scale-95">
              <Plus size={18} />
              <span>Nova Tarefa</span>
           </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col xl:flex-row gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700">
         <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar por serviço, torre, local..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm text-slate-800 dark:text-slate-200 placeholder-slate-400"
            />
         </div>
         <div className="flex flex-wrap items-center gap-2">

            {/* Situation Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Filter size={16} className="text-slate-400" />
                <select 
                value={filterSituation}
                onChange={(e) => setFilterSituation(e.target.value)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="Todos">Todas as Situações</option>
                {settings.situations.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                </select>
            </div>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-slate-50 dark:bg-slate-900 px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700">
                <Calendar size={16} className="text-slate-400" />
                <select 
                value={dateFilter}
                onChange={(e) => setDateFilter(e.target.value as any)}
                className="bg-transparent text-sm text-slate-600 dark:text-slate-300 focus:outline-none"
                >
                <option value="all">Todo o Período</option>
                <option value="week">Esta Semana</option>
                <option value="month">Este Mês</option>
                </select>
            </div>

            {/* Clear Button (Top) */}
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-2 px-3 py-2 text-sm text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors border border-transparent hover:border-red-100"
                >
                    <Eraser size={16} />
                    Limpar
                </button>
            )}
         </div>
      </div>

      {/* Table Container */}
      <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden flex flex-col">
         <div className="overflow-x-auto">
           <table className="w-full text-left border-collapse min-w-[1000px]">
             <thead>
               <tr className="bg-slate-50 dark:bg-slate-700/50 border-b border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 text-xs uppercase font-semibold">
                 <th className="px-3 py-3 w-[25%]">Serviço / Torre</th>
                 <th className="px-3 py-3 w-[15%]">Datas (Ab/In/Fi)</th>
                 <th className="px-3 py-3 w-[15%]">Local / Setor</th>
                 <th className="px-3 py-3">Responsável</th>
                 <th className="px-3 py-3 text-center">Mat.</th>
                 <th className="px-3 py-3 text-center">Situação</th>
                 <th className="px-3 py-3 text-center">Crit.</th>
                 <th className="px-3 py-3 text-right">Ações</th>
               </tr>
             </thead>
             <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-700">
                {filteredTasks.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="px-4 py-8 text-center text-slate-400 dark:text-slate-500">
                       Nenhuma tarefa encontrada.
                    </td>
                  </tr>
                ) : (
                  filteredTasks.map((task) => {
                      const materialNames = getMaterialNames(task.materials);
                      return (
                        <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                            {/* Service / Tower */}
                            <td className="px-3 py-3 align-top">
                                <div className="font-bold text-slate-800 dark:text-slate-200 flex items-start gap-2 text-sm">
                                    <Wrench size={14} className="text-blue-500 shrink-0 mt-0.5" />
                                    <span className="leading-tight">{getServiceName(task.serviceId)}</span>
                                </div>
                                <div className="text-xs font-semibold text-blue-600 dark:text-blue-400 mt-1 pl-6">
                                    {getTowerName(task.towerId)}
                                </div>
                            </td>

                            {/* Consolidated Dates */}
                            <td className="px-3 py-3 align-top">
                                <div className="flex flex-col gap-0.5 text-xs font-mono">
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-slate-400">Ab:</span> 
                                        {formatShortDate(task.callDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-emerald-600 dark:text-emerald-500">In:</span> 
                                        {formatShortDate(task.startDate)}
                                    </div>
                                    <div className="flex items-center gap-1 text-slate-600 dark:text-slate-400">
                                        <span className="font-bold w-6 text-indigo-500">Fi:</span> 
                                        {formatShortDate(task.endDate)}
                                    </div>
                                </div>
                            </td>

                            {/* Location / Sector */}
                            <td className="px-3 py-3 align-top">
                                <div className="text-slate-700 dark:text-slate-300 font-medium text-sm leading-tight truncate max-w-[150px]" title={task.location}>
                                    {task.location}
                                </div>
                                <div className="text-xs text-slate-400 dark:text-slate-500 mt-0.5">
                                    {getSectorName(task.sectorId)}
                                </div>
                            </td>

                            {/* Responsible */}
                            <td className="px-3 py-3 align-top text-slate-600 dark:text-slate-400 text-xs">
                                <div className="truncate max-w-[120px]" title={getResponsibleName(task.responsibleId)}>
                                    {getResponsibleName(task.responsibleId)}
                                </div>
                            </td>

                            {/* Materials */}
                            <td className="px-3 py-3 text-center align-top">
                                {materialNames ? (
                                    <div className="group relative cursor-help flex justify-center">
                                        <span className="w-5 h-5 flex items-center justify-center rounded bg-emerald-100 text-emerald-700 text-[10px] font-bold">
                                            Sim
                                        </span>
                                        <div className="absolute hidden group-hover:block right-0 top-full mt-1 bg-slate-800 text-white text-[10px] p-2 rounded shadow-lg z-10 w-32 text-left">
                                            {materialNames}
                                        </div>
                                    </div>
                                ) : (
                                    <span className="text-slate-300 dark:text-slate-600 text-lg leading-none">-</span>
                                )}
                            </td>

                            {/* Situation */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2 py-0.5 rounded-full text-[10px] font-bold border border-transparent ${getStatusColor(task.situation)}`}>
                                    {task.situation}
                                </span>
                            </td>

                            {/* Criticality */}
                            <td className="px-3 py-3 text-center align-top">
                                <span className={`inline-block px-2 py-0.5 rounded-md text-[10px] font-bold border ${getCriticalityColor(task.criticality)}`}>
                                    {task.criticality}
                                </span>
                            </td>

                            {/* Actions */}
                            <td className="px-3 py-3 text-right align-top">
                                <div className="flex items-center justify-end gap-1">
                                    <button onClick={() => handleEdit(task)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded transition-colors" title="Editar">
                                    <Edit2 size={16} />
                                    </button>
                                    {user?.role === 'admin' && (
                                    <button onClick={() => deleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-colors" title="Excluir">
                                        <Trash2 size={16} />
                                    </button>
                                    )}
                                </div>
                            </td>
                        </tr>
                      );
                  })
                )}
             </tbody>
           </table>
         </div>

         {/* Table Footer with Filter Reset */}
         <div className="border-t border-slate-100 dark:border-slate-700 p-3 bg-slate-50 dark:bg-slate-700/20 flex items-center justify-between">
            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                Total: {filteredTasks.length} {filteredTasks.length === 1 ? 'tarefa encontrada' : 'tarefas encontradas'}
            </span>
            {hasActiveFilters && (
                <button 
                    onClick={handleClearFilters}
                    className="flex items-center gap-1 text-xs font-bold text-red-600 hover:text-red-700 hover:bg-red-50 dark:hover:bg-red-900/20 px-3 py-1.5 rounded transition-colors"
                >
                    <Eraser size={14} />
                    Limpar Tudo
                </button>
            )}
         </div>
      </div>

      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        initialData={editingTask}
      />
    </div>
  );
};

import React, { useState } from 'react';
